-- Florida Bay MariaDB sanitized logical export
-- Current rows are preserved with credentials removed and personal identifiers pseudonymized.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
SET UNIQUE_CHECKS=0;
SET SQL_MODE='NO_AUTO_VALUE_ON_ZERO';

DROP TABLE IF EXISTS `ace_entries`;
CREATE TABLE `ace_entries` (
  `group_name` varchar(64) NOT NULL,
  `object` varchar(120) NOT NULL,
  `mode` enum('allow','deny') NOT NULL DEFAULT 'allow',
  PRIMARY KEY (`group_name`,`object`),
  CONSTRAINT `fk_ace_group` FOREIGN KEY (`group_name`) REFERENCES `ace_groups` (`name`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ace_groups`;
CREATE TABLE `ace_groups` (
  `name` varchar(64) NOT NULL,
  `label` varchar(80) NOT NULL,
  `rank_order` int(11) NOT NULL DEFAULT 0,
  `staff_only` tinyint(1) NOT NULL DEFAULT 0,
  `created_by` varchar(24) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ace_memberships`;
CREATE TABLE `ace_memberships` (
  `discord_id` varchar(24) NOT NULL,
  `group_name` varchar(64) NOT NULL,
  `origin` varchar(96) NOT NULL DEFAULT 'manual',
  `added_by` varchar(24) DEFAULT NULL,
  `added_at` bigint(20) NOT NULL,
  PRIMARY KEY (`discord_id`,`group_name`,`origin`),
  KEY `membership_group` (`group_name`,`discord_id`),
  CONSTRAINT `fk_membership_group` FOREIGN KEY (`group_name`) REFERENCES `ace_groups` (`name`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `activity_cache_finds`;
CREATE TABLE `activity_cache_finds` (
  `license` varchar(100) NOT NULL,
  `day_key` char(10) NOT NULL,
  `cache_id` varchar(40) NOT NULL,
  `character_id` bigint(20) unsigned DEFAULT NULL,
  `found_at` bigint(20) NOT NULL,
  PRIMARY KEY (`license`,`day_key`),
  KEY `activity_cache_day` (`day_key`,`cache_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `activity_profiles`;
CREATE TABLE `activity_profiles` (
  `license` varchar(100) NOT NULL,
  `points` int(10) unsigned NOT NULL DEFAULT 0,
  `completions` int(10) unsigned NOT NULL DEFAULT 0,
  `caches_found` int(10) unsigned NOT NULL DEFAULT 0,
  `cache_streak` int(10) unsigned NOT NULL DEFAULT 0,
  `last_cache_day` char(10) DEFAULT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`license`),
  KEY `activity_points` (`points`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `activity_records`;
CREATE TABLE `activity_records` (
  `license` varchar(100) NOT NULL,
  `character_id` bigint(20) unsigned DEFAULT NULL,
  `challenge_id` varchar(40) NOT NULL,
  `name` varchar(100) NOT NULL,
  `best_ms` int(10) unsigned NOT NULL,
  `completions` int(10) unsigned NOT NULL DEFAULT 1,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`license`,`challenge_id`),
  KEY `activity_challenge_record` (`challenge_id`,`best_ms`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `audit_log`;
CREATE TABLE `audit_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `actor_id` varchar(100) NOT NULL,
  `action` varchar(80) NOT NULL,
  `target_id` varchar(100) DEFAULT NULL,
  `payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`payload`)),
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `audit_actor` (`actor_id`,`created_at`),
  KEY `audit_action` (`action`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=15845 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `audit_mirror_channels`;
CREATE TABLE `audit_mirror_channels` (
  `channel_key` varchar(100) NOT NULL,
  `guild_id` varchar(24) NOT NULL,
  `channel_id` varchar(24) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`channel_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `blacklisted_servers`;
CREATE TABLE `blacklisted_servers` (
  `guild_id` varchar(24) NOT NULL,
  `name` varchar(100) NOT NULL,
  `reason` varchar(300) NOT NULL,
  `added_by` varchar(24) NOT NULL,
  `added_at` bigint(20) NOT NULL,
  `updated_by` varchar(24) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`guild_id`),
  KEY `blacklisted_servers_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `bolos`;
CREATE TABLE `bolos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `kind` enum('person','vehicle') NOT NULL,
  `plate` varchar(8) DEFAULT NULL,
  `description` varchar(500) NOT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_by_id` varchar(32) DEFAULT NULL,
  `created_by` varchar(100) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  `closed_at` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `bolo_active` (`active`,`created_at`),
  KEY `bolo_plate` (`plate`,`active`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `bot_config`;
CREATE TABLE `bot_config` (
  `key` varchar(80) NOT NULL,
  `value` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`value`)),
  `updated_by` varchar(24) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `chain_of_command_config`;
CREATE TABLE `chain_of_command_config` (
  `guild_id` varchar(32) NOT NULL,
  `channel_id` varchar(32) NOT NULL,
  `title` varchar(100) NOT NULL DEFAULT 'Florida Bay Roleplay | Chain of Command',
  `message_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`message_ids`)),
  `updated_by` varchar(32) DEFAULT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`guild_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `chain_of_command_entries`;
CREATE TABLE `chain_of_command_entries` (
  `guild_id` varchar(32) NOT NULL,
  `discord_id` varchar(32) NOT NULL,
  `display_order` int(11) NOT NULL DEFAULT 0,
  `title` varchar(100) DEFAULT NULL,
  `positions` text DEFAULT NULL,
  `assistant_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`assistant_ids`)),
  `color` varchar(7) DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `added_by` varchar(32) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`guild_id`,`discord_id`),
  KEY `coc_entry_order` (`guild_id`,`active`,`display_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `characters`;
CREATE TABLE `characters` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `owner_license` varchar(100) NOT NULL,
  `discord_id` varchar(24) DEFAULT NULL,
  `first_name` varchar(40) NOT NULL,
  `last_name` varchar(40) NOT NULL,
  `date_of_birth` varchar(10) NOT NULL,
  `gender` varchar(24) NOT NULL,
  `backstory` varchar(500) DEFAULT NULL,
  `last_x` double DEFAULT NULL,
  `last_y` double DEFAULT NULL,
  `last_z` double DEFAULT NULL,
  `last_heading` float DEFAULT NULL,
  `last_spawn_key` varchar(40) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  `last_played_at` bigint(20) DEFAULT NULL,
  `archived` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `character_owner` (`owner_license`,`archived`),
  KEY `character_discord` (`discord_id`)
) ENGINE=InnoDB AUTO_INCREMENT=39 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `character_changes`;
CREATE TABLE `character_changes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `character_id` bigint(20) unsigned NOT NULL,
  `field` varchar(16) NOT NULL,
  `old_value` varchar(100) DEFAULT NULL,
  `new_value` varchar(100) DEFAULT NULL,
  `changed_by` varchar(100) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `change_character` (`character_id`,`field`,`created_at`),
  KEY `change_old` (`field`,`old_value`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `character_profiles`;
CREATE TABLE `character_profiles` (
  `character_id` bigint(20) unsigned NOT NULL,
  `nickname` varchar(40) DEFAULT NULL,
  `nationality` varchar(40) DEFAULT NULL,
  `height_cm` smallint(5) unsigned DEFAULT NULL,
  `weight_kg` smallint(5) unsigned DEFAULT NULL,
  `eye_color` varchar(16) DEFAULT NULL,
  `hair_color` varchar(16) DEFAULT NULL,
  `blood_type` varchar(4) DEFAULT NULL,
  `organ_donor` tinyint(1) NOT NULL DEFAULT 0,
  `occupation` varchar(60) DEFAULT NULL,
  `address` varchar(120) DEFAULT NULL,
  `phone` varchar(16) DEFAULT NULL,
  `emergency_contact` varchar(80) DEFAULT NULL,
  `marks` varchar(200) DEFAULT NULL,
  `id_theme` varchar(16) NOT NULL DEFAULT 'classic',
  `show_address` tinyint(1) NOT NULL DEFAULT 0,
  `show_phone` tinyint(1) NOT NULL DEFAULT 0,
  `show_licenses` tinyint(1) NOT NULL DEFAULT 1,
  `updated_at` bigint(20) NOT NULL,
  `phone_from_device` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`character_id`),
  KEY `profile_phone` (`phone`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `command_cooldowns`;
CREATE TABLE `command_cooldowns` (
  `actor_id` varchar(24) NOT NULL,
  `command_key` varchar(64) NOT NULL,
  `expires_at` bigint(20) NOT NULL,
  PRIMARY KEY (`actor_id`,`command_key`),
  KEY `command_cooldown_expiry` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `community_service`;
CREATE TABLE `community_service` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `character_id` bigint(20) unsigned DEFAULT NULL,
  `license` varchar(100) NOT NULL,
  `discord_id` varchar(32) DEFAULT NULL,
  `name` varchar(100) NOT NULL,
  `officer_id` varchar(32) DEFAULT NULL,
  `officer_name` varchar(100) NOT NULL,
  `minutes` int(10) unsigned NOT NULL,
  `charges` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`charges`)),
  `seconds_total` int(10) unsigned NOT NULL,
  `seconds_remaining` int(10) unsigned NOT NULL,
  `collected` int(10) unsigned NOT NULL DEFAULT 0,
  `status` enum('serving','completed','escaped','released','converted') NOT NULL DEFAULT 'serving',
  `created_at` bigint(20) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  `finished_at` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `service_character` (`character_id`,`status`),
  KEY `service_license` (`license`,`status`),
  KEY `service_status` (`status`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `criminal_records`;
CREATE TABLE `criminal_records` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `character_id` bigint(20) unsigned DEFAULT NULL,
  `license` varchar(100) DEFAULT NULL,
  `name` varchar(100) NOT NULL,
  `kind` enum('arrest','citation','warning','service') NOT NULL,
  `charges` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`charges`)),
  `months` int(10) unsigned NOT NULL DEFAULT 0,
  `fine` int(10) unsigned NOT NULL DEFAULT 0,
  `notes` varchar(500) DEFAULT NULL,
  `officer_id` varchar(32) DEFAULT NULL,
  `officer_name` varchar(100) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `record_character` (`character_id`,`created_at`),
  KEY `record_created` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `custom_eup`;
CREATE TABLE `custom_eup` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(40) NOT NULL,
  `label` varchar(60) NOT NULL,
  `notes` varchar(300) DEFAULT NULL,
  `file_count` int(10) unsigned NOT NULL DEFAULT 0,
  `size_bytes` bigint(20) unsigned NOT NULL DEFAULT 0,
  `created_by` varchar(24) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `custom_eup_name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devops_awards`;
CREATE TABLE `devops_awards` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `discord_id` varchar(24) NOT NULL,
  `award` varchar(24) NOT NULL,
  `reason` varchar(500) NOT NULL,
  `actor_id` varchar(24) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `devops_awards_member` (`discord_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devops_config`;
CREATE TABLE `devops_config` (
  `config_key` varchar(64) NOT NULL,
  `config_value` longtext NOT NULL,
  `updated_by` varchar(24) DEFAULT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`config_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devops_discipline`;
CREATE TABLE `devops_discipline` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `discord_id` varchar(24) NOT NULL,
  `kind` varchar(16) NOT NULL,
  `reason` varchar(1000) NOT NULL,
  `actor_id` varchar(24) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  `expires_at` bigint(20) DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `saved_roles` longtext DEFAULT NULL,
  `revoked_by` varchar(24) DEFAULT NULL,
  `revoked_at` bigint(20) DEFAULT NULL,
  `revoke_reason` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `devops_discipline_member` (`discord_id`,`active`),
  KEY `devops_discipline_expiry` (`active`,`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devops_history`;
CREATE TABLE `devops_history` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `discord_id` varchar(24) NOT NULL,
  `action` varchar(32) NOT NULL,
  `from_role` varchar(24) DEFAULT NULL,
  `to_role` varchar(24) DEFAULT NULL,
  `actor_id` varchar(24) NOT NULL,
  `reason` varchar(500) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `devops_history_member` (`discord_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devops_incidents`;
CREATE TABLE `devops_incidents` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(120) NOT NULL,
  `severity` tinyint(4) NOT NULL DEFAULT 3,
  `status` varchar(16) NOT NULL DEFAULT 'investigating',
  `component` varchar(40) DEFAULT NULL,
  `commander_id` varchar(24) DEFAULT NULL,
  `opened_by` varchar(24) NOT NULL,
  `public_channel_id` varchar(24) DEFAULT NULL,
  `public_message_id` varchar(24) DEFAULT NULL,
  `team_channel_id` varchar(24) DEFAULT NULL,
  `team_message_id` varchar(24) DEFAULT NULL,
  `opened_at` bigint(20) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  `resolved_at` bigint(20) DEFAULT NULL,
  `resolved_by` varchar(24) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `devops_incidents_status` (`status`,`opened_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devops_incident_updates`;
CREATE TABLE `devops_incident_updates` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `incident_id` int(10) unsigned NOT NULL,
  `status` varchar(16) NOT NULL,
  `body` varchar(1500) NOT NULL,
  `author_id` varchar(24) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `devops_incident_updates_incident` (`incident_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devops_intake`;
CREATE TABLE `devops_intake` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kind` varchar(16) NOT NULL,
  `discord_id` varchar(24) NOT NULL,
  `username` varchar(80) NOT NULL,
  `answers` longtext NOT NULL,
  `log_message_id` varchar(24) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'open',
  `resolved_by` varchar(24) DEFAULT NULL,
  `resolved_at` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `devops_intake_user` (`discord_id`,`created_at`),
  KEY `devops_intake_status` (`status`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devops_leaves`;
CREATE TABLE `devops_leaves` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `discord_id` varchar(24) NOT NULL,
  `starts_at` bigint(20) NOT NULL,
  `ends_at` bigint(20) NOT NULL,
  `reason` varchar(1000) NOT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'pending',
  `decided_by` varchar(24) DEFAULT NULL,
  `decided_at` bigint(20) DEFAULT NULL,
  `decision_note` varchar(500) DEFAULT NULL,
  `channel_id` varchar(24) DEFAULT NULL,
  `message_id` varchar(24) DEFAULT NULL,
  `role_applied` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `devops_leaves_member` (`discord_id`,`status`),
  KEY `devops_leaves_window` (`status`,`starts_at`,`ends_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devops_members`;
CREATE TABLE `devops_members` (
  `discord_id` varchar(24) NOT NULL,
  `username` varchar(80) NOT NULL,
  `rank_role_id` varchar(24) DEFAULT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'active',
  `joined_at` bigint(20) NOT NULL,
  `rank_changed_at` bigint(20) NOT NULL,
  `trial_ends_at` bigint(20) DEFAULT NULL,
  `trial_notified` tinyint(1) NOT NULL DEFAULT 0,
  `removed_at` bigint(20) DEFAULT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`discord_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devops_ranks`;
CREATE TABLE `devops_ranks` (
  `role_id` varchar(24) NOT NULL,
  `name` varchar(100) NOT NULL,
  `level` int(11) NOT NULL,
  `tier` varchar(32) NOT NULL,
  PRIMARY KEY (`role_id`),
  KEY `devops_ranks_level` (`level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devops_releases`;
CREATE TABLE `devops_releases` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `version` varchar(40) NOT NULL,
  `title` varchar(120) NOT NULL,
  `notes` text NOT NULL,
  `author_id` varchar(24) NOT NULL,
  `channel_id` varchar(24) DEFAULT NULL,
  `message_id` varchar(24) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `devops_releases_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devops_standups`;
CREATE TABLE `devops_standups` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `discord_id` varchar(24) NOT NULL,
  `yesterday` varchar(1000) NOT NULL,
  `today` varchar(1000) NOT NULL,
  `blockers` varchar(1000) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `devops_standups_member` (`discord_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devops_tasks`;
CREATE TABLE `devops_tasks` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(120) NOT NULL,
  `details` varchar(2000) DEFAULT NULL,
  `area` varchar(24) NOT NULL DEFAULT 'general',
  `priority` varchar(10) NOT NULL DEFAULT 'normal',
  `status` varchar(12) NOT NULL DEFAULT 'todo',
  `assignee_id` varchar(24) DEFAULT NULL,
  `creator_id` varchar(24) NOT NULL,
  `due_at` bigint(20) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  `completed_at` bigint(20) DEFAULT NULL,
  `completed_by` varchar(24) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `devops_tasks_status` (`status`,`priority`),
  KEY `devops_tasks_assignee` (`assignee_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devops_tickets`;
CREATE TABLE `devops_tickets` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `guild_id` varchar(24) NOT NULL,
  `author_id` varchar(24) NOT NULL,
  `type` varchar(24) NOT NULL,
  `subject` varchar(100) NOT NULL,
  `status` varchar(12) NOT NULL DEFAULT 'open',
  `priority` tinyint(4) NOT NULL DEFAULT 3,
  `channel_id` varchar(24) DEFAULT NULL,
  `claimed_by` varchar(24) DEFAULT NULL,
  `claimed_at` bigint(20) DEFAULT NULL,
  `first_response_at` bigint(20) DEFAULT NULL,
  `due_at` bigint(20) DEFAULT NULL,
  `overdue_notified` tinyint(1) NOT NULL DEFAULT 0,
  `form_data` longtext DEFAULT NULL,
  `close_requested_by` varchar(24) DEFAULT NULL,
  `close_requested_at` bigint(20) DEFAULT NULL,
  `closed_at` bigint(20) DEFAULT NULL,
  `closed_by` varchar(24) DEFAULT NULL,
  `close_reason` varchar(300) DEFAULT NULL,
  `reopen_count` int(11) NOT NULL DEFAULT 0,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `devops_tickets_author` (`guild_id`,`author_id`,`status`),
  KEY `devops_tickets_open` (`guild_id`,`status`),
  KEY `devops_tickets_channel` (`channel_id`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devops_ticket_events`;
CREATE TABLE `devops_ticket_events` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `ticket_id` int(10) unsigned DEFAULT NULL,
  `event_type` varchar(24) NOT NULL,
  `actor_id` varchar(24) DEFAULT NULL,
  `detail` longtext DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `devops_ticket_events_ticket` (`ticket_id`,`event_type`)
) ENGINE=InnoDB AUTO_INCREMENT=90 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devops_ticket_notes`;
CREATE TABLE `devops_ticket_notes` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `ticket_id` int(10) unsigned NOT NULL,
  `author_id` varchar(24) NOT NULL,
  `body` varchar(1000) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `devops_ticket_notes_ticket` (`ticket_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devops_ticket_participants`;
CREATE TABLE `devops_ticket_participants` (
  `ticket_id` int(10) unsigned NOT NULL,
  `user_id` varchar(24) NOT NULL,
  `added_by` varchar(24) NOT NULL,
  `added_at` bigint(20) NOT NULL,
  PRIMARY KEY (`ticket_id`,`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `dev_submissions`;
CREATE TABLE `dev_submissions` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `repo` varchar(140) NOT NULL,
  `branch` varchar(200) NOT NULL,
  `before_sha` char(40) NOT NULL,
  `head_sha` char(40) NOT NULL,
  `pusher` varchar(100) NOT NULL,
  `commit_count` int(10) unsigned NOT NULL DEFAULT 1,
  `title` varchar(300) NOT NULL,
  `compare_url` varchar(300) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'queued',
  `risk` varchar(10) DEFAULT NULL,
  `static_risk` varchar(10) DEFAULT NULL,
  `ai_model` varchar(60) DEFAULT NULL,
  `analysis` longtext DEFAULT NULL,
  `flags` longtext DEFAULT NULL,
  `files` longtext DEFAULT NULL,
  `diff_excerpt` longtext DEFAULT NULL,
  `analysis_error` varchar(500) DEFAULT NULL,
  `notified_at` bigint(20) DEFAULT NULL,
  `decided_by` varchar(32) DEFAULT NULL,
  `decided_at` bigint(20) DEFAULT NULL,
  `decision_note` varchar(1000) DEFAULT NULL,
  `agent` varchar(10) DEFAULT NULL,
  `run_started_at` bigint(20) DEFAULT NULL,
  `run_finished_at` bigint(20) DEFAULT NULL,
  `run_exit` int(11) DEFAULT NULL,
  `run_log_path` varchar(300) DEFAULT NULL,
  `result_summary` text DEFAULT NULL,
  `result_notified_at` bigint(20) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_dev_submission_push` (`repo`,`head_sha`,`branch`),
  KEY `idx_dev_submission_status` (`status`,`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `discord_channel_bindings`;
CREATE TABLE `discord_channel_bindings` (
  `purpose` varchar(40) NOT NULL,
  `guild_id` varchar(24) NOT NULL,
  `channel_id` varchar(24) NOT NULL,
  `updated_by` varchar(24) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`purpose`),
  UNIQUE KEY `channel_id` (`channel_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `discord_guild_roles`;
CREATE TABLE `discord_guild_roles` (
  `guild_id` varchar(24) NOT NULL,
  `role_id` varchar(24) NOT NULL,
  `name` varchar(100) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`guild_id`,`role_id`),
  KEY `cached_role_name` (`guild_id`,`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `discord_member_cache`;
CREATE TABLE `discord_member_cache` (
  `guild_id` varchar(24) NOT NULL,
  `discord_id` varchar(24) NOT NULL,
  `roles` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`roles`)),
  `nickname` varchar(80) DEFAULT NULL,
  `username` varchar(80) NOT NULL,
  `avatar` varchar(300) DEFAULT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`guild_id`,`discord_id`),
  KEY `cached_member` (`discord_id`,`guild_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `discord_oauth_grants`;
CREATE TABLE `discord_oauth_grants` (
  `discord_id` varchar(24) NOT NULL,
  `token_ciphertext` text NOT NULL,
  `scopes` varchar(500) NOT NULL,
  `expires_at` bigint(20) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`discord_id`),
  KEY `discord_oauth_grants_expiry` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `discord_pending_role_restores`;
CREATE TABLE `discord_pending_role_restores` (
  `guild_id` varchar(24) NOT NULL,
  `discord_id` varchar(24) NOT NULL,
  `roles` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`roles`)),
  `requested_by` varchar(24) NOT NULL,
  `requested_at` bigint(20) NOT NULL,
  `expires_at` bigint(20) NOT NULL,
  PRIMARY KEY (`guild_id`,`discord_id`),
  KEY `pending_restore_expiry` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `discord_role_bindings`;
CREATE TABLE `discord_role_bindings` (
  `guild_id` varchar(24) NOT NULL,
  `role_id` varchar(24) NOT NULL,
  `group_name` varchar(64) NOT NULL,
  PRIMARY KEY (`guild_id`,`role_id`,`group_name`),
  KEY `binding_group` (`group_name`),
  CONSTRAINT `fk_binding_group` FOREIGN KEY (`group_name`) REFERENCES `ace_groups` (`name`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `discord_role_restore_snapshots`;
CREATE TABLE `discord_role_restore_snapshots` (
  `guild_id` varchar(24) NOT NULL,
  `discord_id` varchar(24) NOT NULL,
  `roles` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`roles`)),
  `captured_by` varchar(24) NOT NULL,
  `captured_at` bigint(20) NOT NULL,
  `source` varchar(32) NOT NULL DEFAULT 'global_blacklist',
  PRIMARY KEY (`guild_id`,`discord_id`),
  KEY `restore_snapshot_member` (`discord_id`,`guild_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `discord_role_sources`;
CREATE TABLE `discord_role_sources` (
  `guild_id` varchar(24) NOT NULL,
  `role_id` varchar(24) NOT NULL,
  `group_name` varchar(64) NOT NULL,
  PRIMARY KEY (`guild_id`,`role_id`,`group_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `discord_security_exemptions`;
CREATE TABLE `discord_security_exemptions` (
  `discord_id` varchar(24) NOT NULL,
  `reason` varchar(200) NOT NULL,
  `added_by` varchar(24) NOT NULL,
  `added_at` bigint(20) NOT NULL,
  PRIMARY KEY (`discord_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `discord_security_exemption_scopes`;
CREATE TABLE `discord_security_exemption_scopes` (
  `discord_id` varchar(24) NOT NULL,
  `guild_id` varchar(24) NOT NULL DEFAULT '*',
  `reason` varchar(200) NOT NULL,
  `added_by` varchar(24) NOT NULL,
  `added_at` bigint(20) NOT NULL,
  PRIMARY KEY (`discord_id`,`guild_id`),
  KEY `exemption_scope` (`guild_id`,`discord_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `discord_server_backups`;
CREATE TABLE `discord_server_backups` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `label` varchar(100) DEFAULT NULL,
  `created_by` varchar(32) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  `guild_count` int(10) unsigned NOT NULL DEFAULT 0,
  `skipped` text DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=59 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `discord_server_backup_guilds`;
CREATE TABLE `discord_server_backup_guilds` (
  `backup_id` int(10) unsigned NOT NULL,
  `guild_id` varchar(24) NOT NULL,
  `name` varchar(100) NOT NULL,
  `kind` varchar(20) DEFAULT NULL,
  `roles` int(10) unsigned NOT NULL DEFAULT 0,
  `channels` int(10) unsigned NOT NULL DEFAULT 0,
  `members` int(10) unsigned NOT NULL DEFAULT 0,
  `data` longblob NOT NULL,
  PRIMARY KEY (`backup_id`,`guild_id`),
  CONSTRAINT `fk_server_backup_guild` FOREIGN KEY (`backup_id`) REFERENCES `discord_server_backups` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `dispatch_calls`;
CREATE TABLE `dispatch_calls` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `kind` varchar(16) NOT NULL DEFAULT '911',
  `caller_discord` varchar(24) DEFAULT NULL,
  `caller_name` varchar(80) NOT NULL,
  `message` varchar(300) NOT NULL,
  `location` varchar(120) NOT NULL,
  `x` double NOT NULL,
  `y` double NOT NULL,
  `z` double NOT NULL,
  `status` enum('open','attached','closed') NOT NULL DEFAULT 'open',
  `created_at` bigint(20) NOT NULL,
  `closed_at` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `dispatch_queue` (`status`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `door_settings`;
CREATE TABLE `door_settings` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `group_key` varchar(60) NOT NULL,
  `model` bigint(20) NOT NULL,
  `x` double NOT NULL,
  `y` double NOT NULL,
  `z` double NOT NULL,
  `label` varchar(60) DEFAULT NULL,
  `min_level` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `default_open` tinyint(1) NOT NULL DEFAULT 0,
  `auto_relock` tinyint(1) NOT NULL DEFAULT 1,
  `single` tinyint(1) NOT NULL DEFAULT 0,
  `updated_by` varchar(32) DEFAULT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `door_settings_group` (`group_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fbrp_jail`;
CREATE TABLE `fbrp_jail` (
  `subject` varchar(80) NOT NULL,
  `name` varchar(100) DEFAULT NULL,
  `seconds_total` int(11) NOT NULL,
  `seconds_remaining` int(11) NOT NULL,
  `reason` varchar(255) DEFAULT NULL,
  `officer` varchar(100) DEFAULT NULL,
  `callsign` varchar(32) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`subject`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fbrp_staffjail`;
CREATE TABLE `fbrp_staffjail` (
  `player_key` varchar(80) NOT NULL,
  `name` varchar(120) DEFAULT NULL,
  `seconds_total` int(11) NOT NULL,
  `seconds_remaining` int(11) NOT NULL,
  `reason` varchar(255) DEFAULT NULL,
  `staff` varchar(120) DEFAULT NULL,
  `return_x` float DEFAULT NULL,
  `return_y` float DEFAULT NULL,
  `return_z` float DEFAULT NULL,
  `return_h` float DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`player_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fbrp_trunk_weapons`;
CREATE TABLE `fbrp_trunk_weapons` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `plate` varchar(16) NOT NULL,
  `weapon` varchar(64) NOT NULL,
  `ammo` int(11) NOT NULL DEFAULT 0,
  `clip` int(11) NOT NULL DEFAULT 0,
  `tint` tinyint(4) NOT NULL DEFAULT 0,
  `components` text DEFAULT NULL,
  `stored_by` varchar(64) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_plate` (`plate`)
) ENGINE=InnoDB AUTO_INCREMENT=100 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fishing_catches`;
CREATE TABLE `fishing_catches` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `character_id` bigint(20) unsigned DEFAULT NULL,
  `license` varchar(100) NOT NULL,
  `name` varchar(100) NOT NULL,
  `species` varchar(40) NOT NULL,
  `weight` decimal(6,2) NOT NULL,
  `water` enum('salt','fresh') NOT NULL,
  `rarity` varchar(16) NOT NULL,
  `x` double DEFAULT NULL,
  `y` double DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `catch_species` (`species`,`weight`),
  KEY `catch_license` (`license`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `gg_studio_action_log`;
CREATE TABLE `gg_studio_action_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `resource` varchar(64) NOT NULL,
  `action` varchar(96) NOT NULL,
  `source` int(11) DEFAULT NULL,
  `identifier` varchar(96) DEFAULT NULL,
  `player` varchar(100) DEFAULT NULL,
  `character_name` varchar(100) DEFAULT NULL,
  `data` text DEFAULT NULL,
  `fired_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`) USING BTREE,
  KEY `resource_action` (`resource`,`action`) USING BTREE,
  KEY `identifier` (`identifier`) USING BTREE,
  KEY `fired_at` (`fired_at`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `gg_studio_action_routes`;
CREATE TABLE `gg_studio_action_routes` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `action` varchar(160) NOT NULL,
  `kind` varchar(16) NOT NULL,
  `label` varchar(64) DEFAULT NULL,
  `target` text DEFAULT NULL,
  `message` text DEFAULT NULL,
  `enabled` tinyint(4) NOT NULL DEFAULT 1,
  `created_by` varchar(100) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`) USING BTREE,
  KEY `action` (`action`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `gg_studio_admins`;
CREATE TABLE `gg_studio_admins` (
  `identifier` varchar(96) NOT NULL,
  `name` varchar(100) DEFAULT NULL,
  `granted_by` varchar(100) DEFAULT NULL,
  `granted_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `role` varchar(48) NOT NULL DEFAULT 'admin',
  PRIMARY KEY (`identifier`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `gg_studio_admin_imports`;
CREATE TABLE `gg_studio_admin_imports` (
  `identifier` varchar(96) NOT NULL,
  `imported_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`identifier`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `gg_studio_admin_seen`;
CREATE TABLE `gg_studio_admin_seen` (
  `identifier` varchar(96) NOT NULL,
  `name` varchar(100) DEFAULT NULL,
  `last_open` timestamp NOT NULL DEFAULT current_timestamp(),
  `opens` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`identifier`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `gg_studio_daily`;
CREATE TABLE `gg_studio_daily` (
  `resource` varchar(64) NOT NULL,
  `last_run` bigint(20) NOT NULL DEFAULT 0,
  `ran_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`resource`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `gg_studio_log`;
CREATE TABLE `gg_studio_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `resource` varchar(64) NOT NULL,
  `path` varchar(190) NOT NULL,
  `action` varchar(16) NOT NULL DEFAULT 'change',
  `old_value` text DEFAULT NULL,
  `new_value` text DEFAULT NULL,
  `actor` varchar(100) DEFAULT NULL,
  `changed_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_changed_at` (`changed_at`) USING BTREE,
  KEY `idx_resource` (`resource`,`changed_at`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `gg_studio_migrations`;
CREATE TABLE `gg_studio_migrations` (
  `resource` varchar(64) NOT NULL,
  `key` varchar(190) NOT NULL,
  `applied_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`resource`,`key`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `gg_studio_roles`;
CREATE TABLE `gg_studio_roles` (
  `id` varchar(48) NOT NULL,
  `label` varchar(64) NOT NULL,
  `icon` varchar(48) DEFAULT NULL,
  `permissions` text NOT NULL,
  `created_by` varchar(100) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `gg_studio_settings`;
CREATE TABLE `gg_studio_settings` (
  `resource` varchar(64) NOT NULL,
  `path` varchar(190) NOT NULL,
  `value` mediumtext NOT NULL,
  `updated_by` varchar(100) DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`resource`,`path`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `gg_studio_settings_meta`;
CREATE TABLE `gg_studio_settings_meta` (
  `resource` varchar(64) NOT NULL,
  `revision` bigint(20) NOT NULL DEFAULT 0,
  `version` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`resource`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `giveaways`;
CREATE TABLE `giveaways` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `guild_id` varchar(24) NOT NULL,
  `channel_id` varchar(24) NOT NULL,
  `message_id` varchar(24) DEFAULT NULL,
  `prize` varchar(200) NOT NULL,
  `description` varchar(500) DEFAULT NULL,
  `winner_count` int(11) NOT NULL DEFAULT 1,
  `host_id` varchar(24) NOT NULL,
  `ends_at` bigint(20) NOT NULL,
  `ended` tinyint(1) NOT NULL DEFAULT 0,
  `winners` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`winners`)),
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `giveaway_due` (`ended`,`ends_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `giveaway_entries`;
CREATE TABLE `giveaway_entries` (
  `giveaway_id` int(11) NOT NULL,
  `discord_id` varchar(24) NOT NULL,
  `entered_at` bigint(20) NOT NULL,
  PRIMARY KEY (`giveaway_id`,`discord_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `global_role_strips`;
CREATE TABLE `global_role_strips` (
  `discord_id` varchar(24) NOT NULL,
  `ace_memberships` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`ace_memberships`)),
  `guild_roles` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`guild_roles`)),
  `target_level` int(11) NOT NULL DEFAULT -1,
  `reason` varchar(300) NOT NULL,
  `stripped_by` varchar(24) NOT NULL,
  `stripped_at` bigint(20) NOT NULL,
  `restoring` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`discord_id`),
  KEY `global_role_strips_state` (`restoring`,`stripped_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `headtags`;
CREATE TABLE `headtags` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `kind` enum('head','gang','both') NOT NULL,
  `label` varchar(40) NOT NULL,
  `color` char(7) NOT NULL DEFAULT '#43E8D8',
  `role_id` varchar(24) DEFAULT NULL,
  `guild_id` varchar(24) DEFAULT NULL,
  `org_id` int(10) unsigned DEFAULT NULL,
  `priority` int(11) NOT NULL DEFAULT 0,
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `chat_tag` tinyint(1) NOT NULL DEFAULT 0,
  `outline` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` varchar(24) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `tag_role` (`guild_id`,`role_id`),
  KEY `tag_kind` (`kind`,`priority`),
  KEY `tag_org` (`org_id`),
  CONSTRAINT `fk_headtag_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=98 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `headtag_grants`;
CREATE TABLE `headtag_grants` (
  `discord_id` varchar(24) NOT NULL,
  `tag_id` int(10) unsigned NOT NULL,
  `origin` varchar(96) NOT NULL DEFAULT 'manual',
  `added_by` varchar(24) DEFAULT NULL,
  `added_at` bigint(20) NOT NULL,
  PRIMARY KEY (`discord_id`,`tag_id`,`origin`),
  KEY `fk_tag_grant` (`tag_id`),
  CONSTRAINT `fk_tag_grant` FOREIGN KEY (`tag_id`) REFERENCES `headtags` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `iaa_alerts`;
CREATE TABLE `iaa_alerts` (
  `discord_id` varchar(24) NOT NULL,
  `guild_id` varchar(24) NOT NULL,
  `kind` varchar(16) NOT NULL,
  `alerted_at` bigint(20) NOT NULL,
  PRIMARY KEY (`discord_id`,`guild_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `iaa_altscan_jobs`;
CREATE TABLE `iaa_altscan_jobs` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `guild_ids` text NOT NULL,
  `requested_by` varchar(32) NOT NULL,
  `status` varchar(12) NOT NULL DEFAULT 'queued',
  `progress` varchar(255) DEFAULT NULL,
  `problems` text DEFAULT NULL,
  `requested_at` bigint(20) NOT NULL,
  `started_at` bigint(20) DEFAULT NULL,
  `finished_at` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_iaa_altscan_status` (`status`,`requested_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `iaa_altscan_members`;
CREATE TABLE `iaa_altscan_members` (
  `job_id` bigint(20) NOT NULL,
  `discord_id` varchar(24) NOT NULL,
  `username` varchar(64) DEFAULT NULL,
  `display` varchar(64) DEFAULT NULL,
  `default_avatar` tinyint(1) NOT NULL DEFAULT 0,
  `servers` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`job_id`,`discord_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `iaa_awards`;
CREATE TABLE `iaa_awards` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `discord_id` varchar(24) NOT NULL,
  `award` varchar(32) NOT NULL,
  `citation` varchar(1000) NOT NULL,
  `actor_id` varchar(24) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `iaa_awards_member` (`discord_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `iaa_blacklist`;
CREATE TABLE `iaa_blacklist` (
  `discord_id` varchar(24) NOT NULL,
  `username` varchar(80) NOT NULL,
  `reason` varchar(1000) NOT NULL,
  `actor_id` varchar(24) NOT NULL,
  `case_id` int(10) unsigned DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` bigint(20) NOT NULL,
  `lifted_by` varchar(24) DEFAULT NULL,
  `lifted_at` bigint(20) DEFAULT NULL,
  `lift_reason` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`discord_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `iaa_cases`;
CREATE TABLE `iaa_cases` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `reference` varchar(20) DEFAULT NULL,
  `subject_id` varchar(24) NOT NULL,
  `subject_name` varchar(80) NOT NULL,
  `type` varchar(24) NOT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'open',
  `priority` varchar(10) NOT NULL DEFAULT 'normal',
  `summary` varchar(1500) NOT NULL,
  `opened_by` varchar(24) NOT NULL,
  `lead_id` varchar(24) DEFAULT NULL,
  `thread_id` varchar(24) DEFAULT NULL,
  `file_message_id` varchar(24) DEFAULT NULL,
  `flagged` tinyint(1) NOT NULL DEFAULT 0,
  `notify_subject` tinyint(1) NOT NULL DEFAULT 0,
  `intel` longtext DEFAULT NULL,
  `opened_at` bigint(20) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  `last_activity_at` bigint(20) NOT NULL,
  `reminded_at` bigint(20) DEFAULT NULL,
  `closed_at` bigint(20) DEFAULT NULL,
  `closed_by` varchar(24) DEFAULT NULL,
  `verdict` varchar(24) DEFAULT NULL,
  `outcome` varchar(24) DEFAULT NULL,
  `findings` varchar(2000) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `iaa_cases_reference` (`reference`),
  KEY `iaa_cases_subject` (`subject_id`),
  KEY `iaa_cases_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `iaa_case_entries`;
CREATE TABLE `iaa_case_entries` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `case_id` int(10) unsigned NOT NULL,
  `kind` varchar(16) NOT NULL,
  `author_id` varchar(24) NOT NULL,
  `body` varchar(2000) NOT NULL,
  `url` varchar(500) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `iaa_case_entries_case` (`case_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `iaa_config`;
CREATE TABLE `iaa_config` (
  `config_key` varchar(64) NOT NULL,
  `config_value` longtext NOT NULL,
  `updated_by` varchar(24) DEFAULT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`config_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `iaa_discipline`;
CREATE TABLE `iaa_discipline` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `discord_id` varchar(24) NOT NULL,
  `kind` varchar(16) NOT NULL,
  `reason` varchar(1000) NOT NULL,
  `actor_id` varchar(24) NOT NULL,
  `case_id` int(10) unsigned DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  `expires_at` bigint(20) DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `saved_roles` longtext DEFAULT NULL,
  `revoked_by` varchar(24) DEFAULT NULL,
  `revoked_at` bigint(20) DEFAULT NULL,
  `revoke_reason` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `iaa_discipline_member` (`discord_id`,`active`),
  KEY `iaa_discipline_expiry` (`active`,`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `iaa_history`;
CREATE TABLE `iaa_history` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `discord_id` varchar(24) NOT NULL,
  `action` varchar(32) NOT NULL,
  `from_role` varchar(24) DEFAULT NULL,
  `to_role` varchar(24) DEFAULT NULL,
  `actor_id` varchar(24) NOT NULL,
  `reason` varchar(500) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `iaa_history_member` (`discord_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=76 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `iaa_leaves`;
CREATE TABLE `iaa_leaves` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `discord_id` varchar(24) NOT NULL,
  `starts_at` bigint(20) NOT NULL,
  `ends_at` bigint(20) NOT NULL,
  `reason` varchar(1000) NOT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'pending',
  `role_applied` tinyint(1) NOT NULL DEFAULT 0,
  `decided_by` varchar(24) DEFAULT NULL,
  `decided_at` bigint(20) DEFAULT NULL,
  `decision_note` varchar(500) DEFAULT NULL,
  `channel_id` varchar(24) DEFAULT NULL,
  `message_id` varchar(24) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `iaa_leaves_member` (`discord_id`,`status`),
  KEY `iaa_leaves_status` (`status`,`ends_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `iaa_members`;
CREATE TABLE `iaa_members` (
  `discord_id` varchar(24) NOT NULL,
  `username` varchar(80) NOT NULL,
  `callsign` varchar(16) DEFAULT NULL,
  `rank_role_id` varchar(24) DEFAULT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'active',
  `joined_at` bigint(20) NOT NULL,
  `rank_changed_at` bigint(20) NOT NULL,
  `removed_at` bigint(20) DEFAULT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`discord_id`),
  UNIQUE KEY `iaa_members_callsign` (`callsign`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `iaa_ranks`;
CREATE TABLE `iaa_ranks` (
  `role_id` varchar(24) NOT NULL,
  `name` varchar(100) NOT NULL,
  `level` int(11) NOT NULL,
  `tier` varchar(32) NOT NULL,
  `tier_role_id` varchar(24) DEFAULT NULL,
  PRIMARY KEY (`role_id`),
  KEY `iaa_ranks_level` (`level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `iaa_shifts`;
CREATE TABLE `iaa_shifts` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `discord_id` varchar(24) NOT NULL,
  `started_at` bigint(20) NOT NULL,
  `ended_at` bigint(20) DEFAULT NULL,
  `seconds` int(11) NOT NULL DEFAULT 0,
  `end_reason` varchar(16) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `iaa_shifts_member` (`discord_id`,`started_at`),
  KEY `iaa_shifts_open` (`ended_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `iaa_watch_servers`;
CREATE TABLE `iaa_watch_servers` (
  `guild_id` varchar(24) NOT NULL,
  `name` varchar(100) NOT NULL,
  `reason` varchar(300) NOT NULL,
  `added_by` varchar(24) NOT NULL,
  `added_at` bigint(20) NOT NULL,
  PRIMARY KEY (`guild_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `identity_links`;
CREATE TABLE `identity_links` (
  `discord_id` varchar(24) NOT NULL,
  `kind` varchar(24) NOT NULL,
  `value_hash` char(64) NOT NULL,
  `first_seen` bigint(20) NOT NULL,
  `last_seen` bigint(20) NOT NULL,
  PRIMARY KEY (`discord_id`,`kind`,`value_hash`),
  KEY `identity_lookup` (`value_hash`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `invite_tracker_joins`;
CREATE TABLE `invite_tracker_joins` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `guild_id` varchar(32) NOT NULL,
  `member_id` varchar(32) NOT NULL,
  `inviter_id` varchar(32) DEFAULT NULL,
  `invite_code` varchar(64) DEFAULT NULL,
  `method` enum('invite','vanity','unknown') NOT NULL DEFAULT 'unknown',
  `joined_at` bigint(20) NOT NULL,
  `left_at` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_invite_tracker_inviter` (`guild_id`,`inviter_id`),
  KEY `idx_invite_tracker_member` (`guild_id`,`member_id`,`left_at`)
) ENGINE=InnoDB AUTO_INCREMENT=164 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `jail_sentences`;
CREATE TABLE `jail_sentences` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `character_id` bigint(20) unsigned DEFAULT NULL,
  `license` varchar(100) NOT NULL,
  `discord_id` varchar(32) DEFAULT NULL,
  `name` varchar(100) NOT NULL,
  `officer_id` varchar(32) DEFAULT NULL,
  `officer_name` varchar(100) NOT NULL,
  `months` int(10) unsigned NOT NULL,
  `charges` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`charges`)),
  `seconds_total` int(10) unsigned NOT NULL,
  `seconds_remaining` int(10) unsigned NOT NULL,
  `status` enum('serving','released','escaped') NOT NULL DEFAULT 'serving',
  `release_reason` varchar(40) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  `released_at` bigint(20) DEFAULT NULL,
  `behaviour` int(11) NOT NULL DEFAULT 60,
  `jobs_done` int(10) unsigned NOT NULL DEFAULT 0,
  `reduced_seconds` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `jail_character` (`character_id`,`status`),
  KEY `jail_license` (`license`,`status`),
  KEY `jail_status` (`status`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `jax_water_zones`;
CREATE TABLE `jax_water_zones` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(64) NOT NULL,
  `x` double NOT NULL,
  `y` double NOT NULL,
  `z` double NOT NULL,
  `radius` double NOT NULL DEFAULT 150,
  `created_by` varchar(128) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `mdt_citizen_flags`;
CREATE TABLE `mdt_citizen_flags` (
  `character_id` bigint(20) unsigned NOT NULL,
  `flag` varchar(24) NOT NULL,
  `added_by` varchar(100) NOT NULL,
  `added_at` bigint(20) NOT NULL,
  PRIMARY KEY (`character_id`,`flag`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `mdt_citizen_notes`;
CREATE TABLE `mdt_citizen_notes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `character_id` bigint(20) unsigned NOT NULL,
  `body` varchar(600) NOT NULL,
  `author_id` varchar(32) DEFAULT NULL,
  `author_name` varchar(100) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `note_character` (`character_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `mdt_licenses`;
CREATE TABLE `mdt_licenses` (
  `character_id` bigint(20) unsigned NOT NULL,
  `kind` varchar(16) NOT NULL,
  `status` enum('valid','suspended','revoked','pending') NOT NULL DEFAULT 'valid',
  `points` int(10) unsigned NOT NULL DEFAULT 0,
  `updated_by` varchar(100) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  `issued_at` bigint(20) DEFAULT NULL,
  `restriction` varchar(40) DEFAULT NULL,
  `show_on_id` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`character_id`,`kind`),
  KEY `license_status` (`status`,`updated_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `mdt_reports`;
CREATE TABLE `mdt_reports` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `kind` varchar(24) NOT NULL,
  `title` varchar(120) NOT NULL,
  `location` varchar(120) DEFAULT NULL,
  `narrative` text NOT NULL,
  `citizens` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`citizens`)),
  `officers` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`officers`)),
  `author_id` varchar(32) DEFAULT NULL,
  `author_name` varchar(100) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `report_created` (`created_at`),
  KEY `report_author` (`author_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `mdt_report_addenda`;
CREATE TABLE `mdt_report_addenda` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `report_id` bigint(20) unsigned NOT NULL,
  `body` varchar(2000) NOT NULL,
  `author_id` varchar(32) DEFAULT NULL,
  `author_name` varchar(100) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `addendum_report` (`report_id`,`created_at`),
  CONSTRAINT `fk_report_addendum` FOREIGN KEY (`report_id`) REFERENCES `mdt_reports` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `mdt_report_citizens`;
CREATE TABLE `mdt_report_citizens` (
  `report_id` bigint(20) unsigned NOT NULL,
  `character_id` bigint(20) unsigned NOT NULL,
  `role` varchar(16) NOT NULL DEFAULT 'involved',
  PRIMARY KEY (`report_id`,`character_id`),
  KEY `report_citizen` (`character_id`,`report_id`),
  CONSTRAINT `fk_report_citizen` FOREIGN KEY (`report_id`) REFERENCES `mdt_reports` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `mdt_units`;
CREATE TABLE `mdt_units` (
  `discord_id` varchar(32) NOT NULL,
  `callsign` varchar(12) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`discord_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `member_guilds`;
CREATE TABLE `member_guilds` (
  `discord_id` varchar(24) NOT NULL,
  `guild_id` varchar(24) NOT NULL,
  `guild_name` varchar(100) NOT NULL,
  `is_owner` tinyint(1) NOT NULL DEFAULT 0,
  `first_seen` bigint(20) NOT NULL,
  `last_seen` bigint(20) NOT NULL,
  PRIMARY KEY (`discord_id`,`guild_id`),
  KEY `member_guilds_guild` (`guild_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `member_verifications`;
CREATE TABLE `member_verifications` (
  `discord_id` varchar(24) NOT NULL,
  `verified_at` bigint(20) NOT NULL,
  `last_verified_at` bigint(20) NOT NULL,
  `method` varchar(24) NOT NULL,
  `granted_by` varchar(24) DEFAULT NULL,
  PRIMARY KEY (`discord_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `moderation_appeals`;
CREATE TABLE `moderation_appeals` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `case_id` bigint(20) unsigned NOT NULL,
  `author_id` varchar(24) NOT NULL,
  `ticket_id` bigint(20) unsigned DEFAULT NULL,
  `status` enum('submitted','under_review','info_requested','approved','reduced','denied','withdrawn') NOT NULL DEFAULT 'submitted',
  `statement` text NOT NULL,
  `answers` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`answers`)),
  `evidence` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`evidence`)),
  `response` text DEFAULT NULL,
  `reviewed_by` varchar(24) DEFAULT NULL,
  `assigned_to` varchar(24) DEFAULT NULL,
  `reduced_until` bigint(20) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  `decided_at` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `appeal_author` (`author_id`,`created_at`),
  KEY `appeal_queue` (`status`,`created_at`),
  KEY `fk_appeal_ticket` (`ticket_id`),
  KEY `appeal_case` (`case_id`,`author_id`),
  CONSTRAINT `fk_appeal_case` FOREIGN KEY (`case_id`) REFERENCES `moderation_cases` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_appeal_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `support_tickets` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `moderation_appeal_events`;
CREATE TABLE `moderation_appeal_events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `appeal_id` bigint(20) unsigned NOT NULL,
  `actor_id` varchar(24) NOT NULL,
  `kind` varchar(24) NOT NULL,
  `visibility` enum('member','staff') NOT NULL DEFAULT 'member',
  `body` text DEFAULT NULL,
  `data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`data`)),
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `appeal_event` (`appeal_id`,`created_at`),
  CONSTRAINT `fk_appeal_event` FOREIGN KEY (`appeal_id`) REFERENCES `moderation_appeals` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `moderation_cases`;
CREATE TABLE `moderation_cases` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `ban_id` varchar(24) DEFAULT NULL,
  `guild_id` varchar(24) DEFAULT NULL,
  `target_id` varchar(24) NOT NULL,
  `target_name` varchar(100) DEFAULT NULL,
  `actor_id` varchar(24) NOT NULL,
  `action` varchar(32) NOT NULL,
  `source` varchar(24) NOT NULL DEFAULT 'discord_bot',
  `reason` varchar(300) NOT NULL,
  `expires_at` bigint(20) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `duration_ms` bigint(20) DEFAULT NULL,
  `game_ban_id` int(11) DEFAULT NULL,
  `source_case_id` bigint(20) unsigned DEFAULT NULL,
  `alt_scan` tinyint(1) NOT NULL DEFAULT 0,
  `approval_status` varchar(12) DEFAULT NULL,
  `approval_by` varchar(32) DEFAULT NULL,
  `approval_at` bigint(20) DEFAULT NULL,
  `log_channel_id` varchar(32) DEFAULT NULL,
  `log_message_id` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `moderation_ban_id` (`ban_id`),
  KEY `cases_target` (`target_id`,`created_at`),
  KEY `cases_global` (`guild_id`,`action`,`active`),
  KEY `cases_game_ban` (`game_ban_id`),
  KEY `cases_source` (`source_case_id`)
) ENGINE=InnoDB AUTO_INCREMENT=128 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `network_allowed_bots`;
CREATE TABLE `network_allowed_bots` (
  `bot_id` varchar(24) NOT NULL,
  `label` varchar(80) DEFAULT NULL,
  `added_by` varchar(24) NOT NULL,
  `added_at` bigint(20) NOT NULL,
  PRIMARY KEY (`bot_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `network_bot_adder_allowlist`;
CREATE TABLE `network_bot_adder_allowlist` (
  `guild_id` varchar(24) NOT NULL,
  `subject_type` enum('user','role') NOT NULL,
  `subject_id` varchar(24) NOT NULL,
  `added_by` varchar(24) NOT NULL,
  `added_at` bigint(20) NOT NULL,
  PRIMARY KEY (`guild_id`,`subject_type`,`subject_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `network_guilds`;
CREATE TABLE `network_guilds` (
  `guild_id` varchar(24) NOT NULL,
  `name` varchar(100) NOT NULL,
  `kind` varchar(20) NOT NULL DEFAULT 'other',
  `added_by` varchar(24) NOT NULL,
  `added_at` bigint(20) NOT NULL,
  PRIMARY KEY (`guild_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `network_nuke_offenders`;
CREATE TABLE `network_nuke_offenders` (
  `discord_id` varchar(24) NOT NULL,
  `origin_guild_id` varchar(24) NOT NULL,
  `reason` varchar(300) NOT NULL,
  `punishment` varchar(16) NOT NULL,
  `details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`details`)),
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` bigint(20) NOT NULL,
  `cleared_by` varchar(24) DEFAULT NULL,
  `cleared_at` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`discord_id`),
  KEY `nuke_offender_active` (`active`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `network_role_queue`;
CREATE TABLE `network_role_queue` (
  `guild_id` varchar(24) NOT NULL,
  `discord_id` varchar(24) NOT NULL,
  `role_id` varchar(24) NOT NULL,
  `action` varchar(8) NOT NULL,
  `reason` varchar(200) NOT NULL DEFAULT '',
  `requested_by` varchar(32) NOT NULL,
  `requested_at` bigint(20) NOT NULL,
  `attempts` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`guild_id`,`discord_id`,`role_id`),
  KEY `role_queue_time` (`requested_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `network_security_events`;
CREATE TABLE `network_security_events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `guild_id` varchar(24) NOT NULL,
  `event_type` varchar(48) NOT NULL,
  `actor_id` varchar(24) DEFAULT NULL,
  `target_id` varchar(24) DEFAULT NULL,
  `outcome` varchar(32) NOT NULL,
  `details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`details`)),
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `security_guild` (`guild_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=999 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `network_syncs`;
CREATE TABLE `network_syncs` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `group_name` varchar(64) NOT NULL,
  `role_name` varchar(100) NOT NULL,
  `scope` varchar(16) NOT NULL DEFAULT 'all',
  `permissions` varchar(24) NOT NULL DEFAULT '0',
  `color` int(10) unsigned NOT NULL DEFAULT 0,
  `hoist` tinyint(1) NOT NULL DEFAULT 0,
  `mentionable` tinyint(1) NOT NULL DEFAULT 0,
  `all_channels` tinyint(1) NOT NULL DEFAULT 0,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_by` varchar(24) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  `placement` varchar(8) NOT NULL DEFAULT 'top',
  PRIMARY KEY (`id`),
  UNIQUE KEY `group_name` (`group_name`),
  CONSTRAINT `fk_sync_group` FOREIGN KEY (`group_name`) REFERENCES `ace_groups` (`name`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `network_sync_anchors`;
CREATE TABLE `network_sync_anchors` (
  `sync_id` int(10) unsigned NOT NULL,
  `guild_id` varchar(24) NOT NULL,
  `below_role_id` varchar(24) NOT NULL,
  PRIMARY KEY (`sync_id`,`guild_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `network_sync_guilds`;
CREATE TABLE `network_sync_guilds` (
  `sync_id` int(10) unsigned NOT NULL,
  `guild_id` varchar(24) NOT NULL,
  PRIMARY KEY (`sync_id`,`guild_id`),
  CONSTRAINT `fk_sync_guild_sync` FOREIGN KEY (`sync_id`) REFERENCES `network_syncs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `network_sync_guild_settings`;
CREATE TABLE `network_sync_guild_settings` (
  `sync_id` int(10) unsigned NOT NULL,
  `guild_id` varchar(24) NOT NULL,
  `permissions` varchar(24) NOT NULL DEFAULT '0',
  `all_channels` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`sync_id`,`guild_id`),
  CONSTRAINT `fk_sync_guild_settings_sync` FOREIGN KEY (`sync_id`) REFERENCES `network_syncs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `network_sync_queue`;
CREATE TABLE `network_sync_queue` (
  `discord_id` varchar(24) NOT NULL,
  `requested_by` varchar(32) NOT NULL,
  `requested_at` bigint(20) NOT NULL,
  PRIMARY KEY (`discord_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `network_sync_roles`;
CREATE TABLE `network_sync_roles` (
  `sync_id` int(10) unsigned NOT NULL,
  `guild_id` varchar(24) NOT NULL,
  `role_id` varchar(24) NOT NULL,
  `managed` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`sync_id`,`guild_id`),
  UNIQUE KEY `sync_role` (`guild_id`,`role_id`),
  CONSTRAINT `fk_sync_role` FOREIGN KEY (`sync_id`) REFERENCES `network_syncs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `offices`;
CREATE TABLE `offices` (
  `guild_id` varchar(24) NOT NULL,
  `channel_id` varchar(24) NOT NULL,
  `owner_id` varchar(24) NOT NULL,
  `set_by` varchar(24) NOT NULL,
  `set_at` bigint(20) NOT NULL,
  PRIMARY KEY (`guild_id`,`channel_id`),
  KEY `office_owner` (`guild_id`,`owner_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `organizations`;
CREATE TABLE `organizations` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(40) NOT NULL,
  `name` varchar(80) NOT NULL,
  `type` enum('gang','business','leo','fire','government','other') NOT NULL DEFAULT 'other',
  `color` char(7) NOT NULL DEFAULT '#43E8D8',
  `tag_id` int(10) unsigned NOT NULL,
  `ace_group` varchar(64) DEFAULT NULL,
  `guild_id` varchar(24) DEFAULT NULL,
  `role_id` varchar(24) DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` varchar(24) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `motd` varchar(300) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `fk_org_tag` (`tag_id`),
  KEY `fk_org_group` (`ace_group`),
  CONSTRAINT `fk_org_group` FOREIGN KEY (`ace_group`) REFERENCES `ace_groups` (`name`) ON DELETE SET NULL,
  CONSTRAINT `fk_org_tag` FOREIGN KEY (`tag_id`) REFERENCES `headtags` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `organization_duty_global_access`;
CREATE TABLE `organization_duty_global_access` (
  `discord_id` varchar(32) NOT NULL,
  `added_by` varchar(32) DEFAULT NULL,
  `added_at` bigint(20) NOT NULL,
  PRIMARY KEY (`discord_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `organization_members`;
CREATE TABLE `organization_members` (
  `org_id` int(10) unsigned NOT NULL,
  `discord_id` varchar(24) NOT NULL,
  `rank_name` varchar(60) NOT NULL DEFAULT 'Member',
  `manager` tinyint(1) NOT NULL DEFAULT 0,
  `added_by` varchar(24) DEFAULT NULL,
  `added_at` bigint(20) NOT NULL,
  `rank_id` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`org_id`,`discord_id`),
  KEY `org_member` (`discord_id`,`org_id`),
  CONSTRAINT `fk_org_member_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `organization_role_requirements`;
CREATE TABLE `organization_role_requirements` (
  `org_id` int(10) unsigned NOT NULL,
  `guild_id` varchar(24) NOT NULL,
  `role_id` varchar(24) NOT NULL,
  `added_by` varchar(24) NOT NULL,
  `added_at` bigint(20) NOT NULL,
  PRIMARY KEY (`org_id`,`guild_id`,`role_id`),
  KEY `organization_requirement_role` (`guild_id`,`role_id`),
  CONSTRAINT `fk_org_requirement_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `organization_shifts`;
CREATE TABLE `organization_shifts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `org_id` int(10) unsigned NOT NULL,
  `discord_id` varchar(24) NOT NULL,
  `player_id` int(10) unsigned DEFAULT NULL,
  `name` varchar(80) NOT NULL,
  `started_at` bigint(20) NOT NULL,
  `ended_at` bigint(20) DEFAULT NULL,
  `heartbeat_at` bigint(20) NOT NULL,
  `seconds` int(10) unsigned NOT NULL DEFAULT 0,
  `end_reason` varchar(24) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `org_shift_member` (`org_id`,`discord_id`,`started_at`),
  KEY `org_shift_open` (`ended_at`),
  CONSTRAINT `fk_org_shift_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=169 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_announcements`;
CREATE TABLE `org_announcements` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `org_id` int(10) unsigned NOT NULL,
  `title` varchar(120) NOT NULL,
  `body` varchar(2000) NOT NULL,
  `pinned` tinyint(1) NOT NULL DEFAULT 0,
  `author_id` varchar(32) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `org_announcement_lookup` (`org_id`,`pinned`,`id`),
  CONSTRAINT `fk_announcement_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_applications`;
CREATE TABLE `org_applications` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `org_id` int(10) unsigned NOT NULL,
  `discord_id` varchar(24) NOT NULL,
  `answers` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`answers`)),
  `status` enum('pending','accepted','denied','withdrawn') NOT NULL DEFAULT 'pending',
  `reviewer_id` varchar(32) DEFAULT NULL,
  `review_note` varchar(500) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  `reviewed_at` bigint(20) DEFAULT NULL,
  `join_state` varchar(24) DEFAULT NULL,
  `join_guild_id` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `org_application_queue` (`org_id`,`status`,`id`),
  KEY `org_application_member` (`discord_id`,`org_id`),
  CONSTRAINT `fk_application_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_application_logs`;
CREATE TABLE `org_application_logs` (
  `org_id` int(10) unsigned NOT NULL,
  `guild_id` varchar(32) NOT NULL,
  `channel_id` varchar(32) NOT NULL,
  `ping_role_id` varchar(32) DEFAULT NULL,
  `buttons` tinyint(1) NOT NULL DEFAULT 1,
  `updated_by` varchar(32) DEFAULT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`org_id`),
  CONSTRAINT `fk_org_application_log_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_application_messages`;
CREATE TABLE `org_application_messages` (
  `application_id` bigint(20) unsigned NOT NULL,
  `channel_id` varchar(32) NOT NULL,
  `message_id` varchar(32) NOT NULL,
  `kind` varchar(8) NOT NULL,
  PRIMARY KEY (`application_id`,`channel_id`),
  CONSTRAINT `fk_org_application_message_app` FOREIGN KEY (`application_id`) REFERENCES `org_applications` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_badge_rank_tiers`;
CREATE TABLE `org_badge_rank_tiers` (
  `org_id` int(10) unsigned NOT NULL,
  `rank_id` int(10) unsigned NOT NULL,
  `tier` varchar(16) NOT NULL,
  PRIMARY KEY (`org_id`,`rank_id`),
  KEY `fk_badge_rank_rank` (`rank_id`),
  CONSTRAINT `fk_badge_rank_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_badge_rank_rank` FOREIGN KEY (`rank_id`) REFERENCES `org_ranks` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_badge_templates`;
CREATE TABLE `org_badge_templates` (
  `org_id` int(10) unsigned NOT NULL,
  `tier` varchar(16) NOT NULL,
  `mime` varchar(24) NOT NULL,
  `data` mediumblob NOT NULL,
  `bytes` int(10) unsigned NOT NULL,
  `fields` text NOT NULL,
  `updated_by` varchar(32) DEFAULT NULL,
  `updated_at` bigint(20) NOT NULL,
  `original` mediumblob DEFAULT NULL,
  `detected_at` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`org_id`,`tier`),
  CONSTRAINT `fk_badge_tpl_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_divisions`;
CREATE TABLE `org_divisions` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `org_id` int(10) unsigned NOT NULL,
  `name` varchar(40) NOT NULL,
  `color` char(7) DEFAULT NULL,
  `description` varchar(160) DEFAULT NULL,
  `sort_order` smallint(6) NOT NULL DEFAULT 0,
  `created_by` varchar(32) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `org_division_name` (`org_id`,`name`),
  CONSTRAINT `fk_division_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_drug_runs`;
CREATE TABLE `org_drug_runs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `org_id` int(10) unsigned DEFAULT NULL,
  `discord_id` varchar(32) DEFAULT NULL,
  `character_id` bigint(20) unsigned DEFAULT NULL,
  `name` varchar(100) NOT NULL,
  `drug` varchar(16) NOT NULL,
  `units` int(10) unsigned NOT NULL,
  `payout` int(10) unsigned NOT NULL DEFAULT 0,
  `status` enum('delivered','seized','confiscated') NOT NULL,
  `seized_by` varchar(100) DEFAULT NULL,
  `location` varchar(80) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  `seized_org_id` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `drug_run_org` (`org_id`,`created_at`),
  KEY `drug_run_status` (`status`,`created_at`),
  KEY `drug_run_seizer` (`seized_org_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_events`;
CREATE TABLE `org_events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `org_id` int(10) unsigned NOT NULL,
  `title` varchar(80) NOT NULL,
  `description` varchar(1000) DEFAULT NULL,
  `location` varchar(80) DEFAULT NULL,
  `starts_at` bigint(20) NOT NULL,
  `created_by` varchar(32) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  `cancelled_at` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `org_events_lookup` (`org_id`,`starts_at`),
  CONSTRAINT `fk_org_event_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_event_rsvps`;
CREATE TABLE `org_event_rsvps` (
  `event_id` bigint(20) unsigned NOT NULL,
  `org_id` int(10) unsigned NOT NULL,
  `discord_id` varchar(24) NOT NULL,
  `response` enum('going','maybe','no') NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`event_id`,`discord_id`),
  KEY `org_event_rsvp_org` (`org_id`),
  CONSTRAINT `fk_org_event_rsvp_event` FOREIGN KEY (`event_id`) REFERENCES `org_events` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_logos`;
CREATE TABLE `org_logos` (
  `org_id` int(10) unsigned NOT NULL,
  `mime` varchar(24) NOT NULL,
  `data` mediumblob NOT NULL,
  `bytes` int(10) unsigned NOT NULL,
  `updated_by` varchar(32) DEFAULT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`org_id`),
  CONSTRAINT `fk_org_logo_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_member_profiles`;
CREATE TABLE `org_member_profiles` (
  `org_id` int(10) unsigned NOT NULL,
  `discord_id` varchar(24) NOT NULL,
  `callsign` varchar(16) DEFAULT NULL,
  `division_id` int(10) unsigned DEFAULT NULL,
  `status` enum('active','loa','probation','inactive','suspended') NOT NULL DEFAULT 'active',
  `status_note` varchar(160) DEFAULT NULL,
  `status_until` bigint(20) DEFAULT NULL,
  `updated_by` varchar(32) DEFAULT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`org_id`,`discord_id`),
  UNIQUE KEY `org_member_callsign` (`org_id`,`callsign`),
  KEY `org_member_division` (`division_id`),
  CONSTRAINT `fk_member_profile_division` FOREIGN KEY (`division_id`) REFERENCES `org_divisions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_member_profile_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_member_records`;
CREATE TABLE `org_member_records` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `org_id` int(10) unsigned NOT NULL,
  `discord_id` varchar(24) NOT NULL,
  `kind` enum('promotion','demotion','commendation','strike','note') NOT NULL,
  `body` varchar(500) NOT NULL,
  `actor_id` varchar(32) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  `revoked_by` varchar(32) DEFAULT NULL,
  `revoked_at` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `org_member_record_lookup` (`org_id`,`discord_id`,`id`),
  CONSTRAINT `fk_member_record_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_profiles`;
CREATE TABLE `org_profiles` (
  `org_id` int(10) unsigned NOT NULL,
  `tagline` varchar(120) DEFAULT NULL,
  `about` varchar(2000) DEFAULT NULL,
  `discord_invite` varchar(120) DEFAULT NULL,
  `recruiting` tinyint(1) NOT NULL DEFAULT 0,
  `questions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`questions`)),
  `public_roster` tinyint(1) NOT NULL DEFAULT 1,
  `updated_by` varchar(32) DEFAULT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`org_id`),
  CONSTRAINT `fk_org_profile_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_properties`;
CREATE TABLE `org_properties` (
  `item_key` varchar(40) NOT NULL,
  `org_id` int(10) unsigned NOT NULL,
  `purchased_by` varchar(32) NOT NULL,
  `purchased_at` bigint(20) NOT NULL,
  `setup_status` varchar(10) NOT NULL DEFAULT 'pending',
  `setup_by` varchar(32) DEFAULT NULL,
  `setup_at` bigint(20) DEFAULT NULL,
  `setup_channel_id` varchar(24) DEFAULT NULL,
  `setup_message_id` varchar(24) DEFAULT NULL,
  PRIMARY KEY (`item_key`),
  KEY `property_org` (`org_id`),
  CONSTRAINT `fk_property_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_purchases`;
CREATE TABLE `org_purchases` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `org_id` int(10) unsigned NOT NULL,
  `item_key` varchar(40) NOT NULL,
  `kind` varchar(16) NOT NULL,
  `label` varchar(80) NOT NULL,
  `price` int(10) unsigned NOT NULL,
  `purchased_by` varchar(32) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `org_item` (`org_id`,`item_key`),
  KEY `purchase_item` (`item_key`),
  CONSTRAINT `fk_purchase_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_ranks`;
CREATE TABLE `org_ranks` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `org_id` int(10) unsigned NOT NULL,
  `name` varchar(40) NOT NULL,
  `level` tinyint(3) unsigned NOT NULL DEFAULT 10,
  `can_spend` tinyint(1) NOT NULL DEFAULT 0,
  `can_roster` tinyint(1) NOT NULL DEFAULT 0,
  `can_armory` tinyint(1) NOT NULL DEFAULT 1,
  `can_garage` tinyint(1) NOT NULL DEFAULT 1,
  `spend_limit` int(10) unsigned DEFAULT NULL,
  `created_by` varchar(32) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  `color` char(7) DEFAULT NULL,
  `description` varchar(160) DEFAULT NULL,
  `can_sell` tinyint(1) NOT NULL DEFAULT 0,
  `can_ranks` tinyint(1) NOT NULL DEFAULT 0,
  `can_motd` tinyint(1) NOT NULL DEFAULT 0,
  `can_ledger` tinyint(1) NOT NULL DEFAULT 1,
  `can_announce` tinyint(1) NOT NULL DEFAULT 0,
  `can_discipline` tinyint(1) NOT NULL DEFAULT 0,
  `can_applications` tinyint(1) NOT NULL DEFAULT 0,
  `can_profile` tinyint(1) NOT NULL DEFAULT 0,
  `min_weekly_minutes` smallint(5) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `org_rank_name` (`org_id`,`name`),
  KEY `org_rank_level` (`org_id`,`level`),
  CONSTRAINT `fk_rank_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_rank_roles`;
CREATE TABLE `org_rank_roles` (
  `rank_id` int(10) unsigned NOT NULL,
  `org_id` int(10) unsigned NOT NULL,
  `guild_id` varchar(24) NOT NULL,
  `role_id` varchar(24) NOT NULL,
  `added_by` varchar(32) DEFAULT NULL,
  `added_at` bigint(20) NOT NULL,
  PRIMARY KEY (`rank_id`,`guild_id`,`role_id`),
  KEY `org_rank_role_org` (`org_id`,`added_at`),
  CONSTRAINT `fk_rank_role_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_rank_role_rank` FOREIGN KEY (`rank_id`) REFERENCES `org_ranks` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_roster_log`;
CREATE TABLE `org_roster_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `org_id` int(10) unsigned NOT NULL,
  `actor_id` varchar(32) NOT NULL,
  `action` varchar(32) NOT NULL,
  `target_id` varchar(32) DEFAULT NULL,
  `detail` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`detail`)),
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `org_roster_log_lookup` (`org_id`,`id`),
  CONSTRAINT `fk_roster_log_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=212 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_roster_settings`;
CREATE TABLE `org_roster_settings` (
  `org_id` int(10) unsigned NOT NULL,
  `role_sync` tinyint(1) NOT NULL DEFAULT 1,
  `auto_rank` tinyint(1) NOT NULL DEFAULT 0,
  `updated_by` varchar(32) DEFAULT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`org_id`),
  CONSTRAINT `fk_roster_settings_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_shop_items`;
CREATE TABLE `org_shop_items` (
  `item_key` varchar(40) NOT NULL,
  `kind` enum('property','vehicle','weapon','outfit','perk') NOT NULL,
  `label` varchar(80) NOT NULL,
  `description` varchar(300) NOT NULL DEFAULT '',
  `price` int(10) unsigned NOT NULL,
  `org_types` varchar(80) NOT NULL DEFAULT 'gang,business',
  `data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`data`)),
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `stock` int(10) unsigned DEFAULT NULL,
  `requires` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`item_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_transactions`;
CREATE TABLE `org_transactions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `org_id` int(10) unsigned NOT NULL,
  `amount` bigint(20) NOT NULL,
  `balance_after` bigint(20) NOT NULL,
  `kind` varchar(24) NOT NULL,
  `description` varchar(200) NOT NULL,
  `actor_id` varchar(32) DEFAULT NULL,
  `ref` varchar(64) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `org_tx` (`org_id`,`created_at`),
  KEY `org_tx_kind` (`kind`,`created_at`),
  KEY `org_tx_actor` (`org_id`,`actor_id`,`created_at`),
  CONSTRAINT `fk_tx_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=360 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `org_wallets`;
CREATE TABLE `org_wallets` (
  `org_id` int(10) unsigned NOT NULL,
  `balance` bigint(20) NOT NULL DEFAULT 0,
  `lifetime_earned` bigint(20) NOT NULL DEFAULT 0,
  `lifetime_spent` bigint(20) NOT NULL DEFAULT 0,
  `updated_at` bigint(20) NOT NULL DEFAULT 0,
  PRIMARY KEY (`org_id`),
  CONSTRAINT `fk_wallet_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `outfit_shares`;
CREATE TABLE `outfit_shares` (
  `code` varchar(9) NOT NULL,
  `owner_license` varchar(100) NOT NULL,
  `owner_discord` varchar(32) DEFAULT NULL,
  `owner_name` varchar(80) NOT NULL,
  `character_name` varchar(40) NOT NULL,
  `payload` mediumtext NOT NULL,
  `copies` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`code`),
  KEY `idx_outfit_shares_owner` (`owner_license`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ox_doorlock`;
CREATE TABLE `ox_doorlock` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL,
  `data` longtext NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `passport_daily_progress`;
CREATE TABLE `passport_daily_progress` (
  `license` varchar(100) NOT NULL,
  `day_key` char(10) NOT NULL,
  `goal_id` varchar(24) NOT NULL,
  `progress` int(10) unsigned NOT NULL DEFAULT 0,
  `completed_at` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`license`,`day_key`,`goal_id`),
  KEY `passport_daily` (`day_key`,`completed_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `passport_discoveries`;
CREATE TABLE `passport_discoveries` (
  `license` varchar(100) NOT NULL,
  `landmark_id` varchar(40) NOT NULL,
  `character_id` bigint(20) unsigned DEFAULT NULL,
  `discovered_at` bigint(20) NOT NULL,
  PRIMARY KEY (`license`,`landmark_id`),
  KEY `passport_landmark` (`landmark_id`,`discovered_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `passport_profiles`;
CREATE TABLE `passport_profiles` (
  `license` varchar(100) NOT NULL,
  `points` int(10) unsigned NOT NULL DEFAULT 0,
  `discoveries` int(10) unsigned NOT NULL DEFAULT 0,
  `daily_completed` int(10) unsigned NOT NULL DEFAULT 0,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`license`),
  KEY `passport_points` (`points`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `pastime_achievements`;
CREATE TABLE `pastime_achievements` (
  `license` varchar(100) NOT NULL,
  `achievement_id` varchar(40) NOT NULL,
  `unlocked_at` bigint(20) NOT NULL,
  PRIMARY KEY (`license`,`achievement_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `pastime_duels`;
CREATE TABLE `pastime_duels` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `winner_license` varchar(100) NOT NULL,
  `loser_license` varchar(100) NOT NULL,
  `winner_name` varchar(100) NOT NULL,
  `loser_name` varchar(100) NOT NULL,
  `meters` int(10) unsigned NOT NULL DEFAULT 0,
  `duration_ms` int(10) unsigned NOT NULL DEFAULT 0,
  `rating_delta` int(11) NOT NULL DEFAULT 0,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `pastime_duel_winner` (`winner_license`),
  KEY `pastime_duel_loser` (`loser_license`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `pastime_goal_claims`;
CREATE TABLE `pastime_goal_claims` (
  `week_key` char(10) NOT NULL,
  `goal_id` varchar(40) NOT NULL,
  `license` varchar(100) NOT NULL,
  `claimed_at` bigint(20) NOT NULL,
  PRIMARY KEY (`week_key`,`goal_id`,`license`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `pastime_job_stats`;
CREATE TABLE `pastime_job_stats` (
  `license` varchar(100) NOT NULL,
  `job_id` varchar(40) NOT NULL,
  `completions` int(10) unsigned NOT NULL DEFAULT 0,
  `best_ms` int(10) unsigned DEFAULT NULL,
  `rep_total` int(10) unsigned NOT NULL DEFAULT 0,
  `meters_total` bigint(20) unsigned NOT NULL DEFAULT 0,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`license`,`job_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `pastime_log`;
CREATE TABLE `pastime_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `license` varchar(100) NOT NULL,
  `kind` varchar(24) NOT NULL,
  `ref` varchar(40) DEFAULT NULL,
  `amount` int(11) NOT NULL DEFAULT 1,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `pastime_log_kind` (`kind`,`created_at`),
  KEY `pastime_log_license` (`license`,`kind`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `pastime_profiles`;
CREATE TABLE `pastime_profiles` (
  `license` varchar(100) NOT NULL,
  `name` varchar(100) NOT NULL DEFAULT '',
  `rep` int(10) unsigned NOT NULL DEFAULT 0,
  `jobs_done` int(10) unsigned NOT NULL DEFAULT 0,
  `drops_won` int(10) unsigned NOT NULL DEFAULT 0,
  `duels_won` int(10) unsigned NOT NULL DEFAULT 0,
  `duels_lost` int(10) unsigned NOT NULL DEFAULT 0,
  `duel_streak` int(10) unsigned NOT NULL DEFAULT 0,
  `best_duel_streak` int(10) unsigned NOT NULL DEFAULT 0,
  `duel_rating` int(11) NOT NULL DEFAULT 1000,
  `skydives` int(10) unsigned NOT NULL DEFAULT 0,
  `bullseyes` int(10) unsigned NOT NULL DEFAULT 0,
  `daily_streak` int(10) unsigned NOT NULL DEFAULT 0,
  `best_daily_streak` int(10) unsigned NOT NULL DEFAULT 0,
  `last_daily_day` char(10) DEFAULT NULL,
  `title` varchar(40) DEFAULT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`license`),
  KEY `pastime_rep` (`rep`),
  KEY `pastime_rating` (`duel_rating`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `pastime_skydive_records`;
CREATE TABLE `pastime_skydive_records` (
  `license` varchar(100) NOT NULL,
  `jump_id` varchar(40) NOT NULL,
  `name` varchar(100) NOT NULL,
  `best_cm` int(10) unsigned NOT NULL,
  `attempts` int(10) unsigned NOT NULL DEFAULT 1,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`license`,`jump_id`),
  KEY `pastime_skydive_best` (`jump_id`,`best_cm`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `personal_liveries`;
CREATE TABLE `personal_liveries` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `personal_id` int(10) unsigned NOT NULL,
  `label` varchar(60) NOT NULL,
  `token` varchar(24) NOT NULL,
  `files` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`files`)),
  `added_by` varchar(24) DEFAULT NULL,
  `added_at` bigint(20) NOT NULL,
  `builtin` tinyint(1) NOT NULL DEFAULT 0,
  `detail` varchar(200) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `personal_livery_label` (`personal_id`,`label`),
  CONSTRAINT `fk_personal_livery` FOREIGN KEY (`personal_id`) REFERENCES `personal_vehicles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `personal_vehicles`;
CREATE TABLE `personal_vehicles` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `model` varchar(40) NOT NULL,
  `label` varchar(60) NOT NULL,
  `plate` varchar(8) DEFAULT NULL,
  `owner_id` varchar(24) NOT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `bulletproof` tinyint(1) NOT NULL DEFAULT 0,
  `emergency_class` varchar(16) NOT NULL DEFAULT 'civilian',
  `locked` tinyint(1) NOT NULL DEFAULT 0,
  `locked_by` varchar(32) DEFAULT NULL,
  `locked_at` bigint(20) DEFAULT NULL,
  `created_by` varchar(24) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `personal_plate` (`plate`),
  KEY `personal_owner` (`owner_id`),
  KEY `personal_model` (`model`)
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `personal_vehicle_tags`;
CREATE TABLE `personal_vehicle_tags` (
  `personal_id` int(10) unsigned NOT NULL,
  `tag_id` int(10) unsigned NOT NULL,
  `added_by` varchar(24) DEFAULT NULL,
  `added_at` bigint(20) NOT NULL,
  PRIMARY KEY (`personal_id`,`tag_id`),
  UNIQUE KEY `personal_one_tag` (`personal_id`),
  KEY `personal_tag_lookup` (`tag_id`),
  CONSTRAINT `fk_personal_tag_tag` FOREIGN KEY (`tag_id`) REFERENCES `headtags` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_personal_tag_vehicle` FOREIGN KEY (`personal_id`) REFERENCES `personal_vehicles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `personal_vehicle_trust`;
CREATE TABLE `personal_vehicle_trust` (
  `personal_id` int(10) unsigned NOT NULL,
  `discord_id` varchar(24) NOT NULL,
  `added_by` varchar(24) DEFAULT NULL,
  `added_at` bigint(20) NOT NULL,
  PRIMARY KEY (`personal_id`,`discord_id`),
  KEY `personal_trust_member` (`discord_id`),
  CONSTRAINT `fk_personal_trust` FOREIGN KEY (`personal_id`) REFERENCES `personal_vehicles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `players`;
CREATE TABLE `players` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `license` varchar(100) NOT NULL,
  `discord_id` varchar(24) DEFAULT NULL,
  `name` varchar(80) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `last_seen` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `license` (`license`),
  KEY `player_discord` (`discord_id`),
  KEY `player_seen` (`last_seen`)
) ENGINE=InnoDB AUTO_INCREMENT=591 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `player_character_selection`;
CREATE TABLE `player_character_selection` (
  `owner_license` varchar(100) NOT NULL,
  `character_id` bigint(20) unsigned NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`owner_license`),
  KEY `fk_character_selection` (`character_id`),
  CONSTRAINT `fk_character_selection` FOREIGN KEY (`character_id`) REFERENCES `characters` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `player_contraband`;
CREATE TABLE `player_contraband` (
  `owner_key` varchar(120) NOT NULL,
  `org_id` int(10) unsigned DEFAULT NULL,
  `drug` varchar(16) NOT NULL,
  `units` int(10) unsigned NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`owner_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `player_identifiers`;
CREATE TABLE `player_identifiers` (
  `player_id` int(10) unsigned NOT NULL,
  `identifier` varchar(160) NOT NULL,
  PRIMARY KEY (`player_id`,`identifier`),
  KEY `identifier_lookup` (`identifier`),
  CONSTRAINT `fk_identifier_player` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `player_playtime`;
CREATE TABLE `player_playtime` (
  `license` varchar(100) NOT NULL,
  `discord_id` varchar(24) DEFAULT NULL,
  `name` varchar(80) NOT NULL,
  `seconds` bigint(20) unsigned NOT NULL DEFAULT 0,
  `sessions` int(10) unsigned NOT NULL DEFAULT 0,
  `afk_kicks` int(10) unsigned NOT NULL DEFAULT 0,
  `first_seen` bigint(20) NOT NULL,
  `last_seen` bigint(20) NOT NULL,
  PRIMARY KEY (`license`),
  KEY `playtime_discord` (`discord_id`),
  KEY `playtime_seconds` (`seconds`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `player_tag_selection`;
CREATE TABLE `player_tag_selection` (
  `discord_id` varchar(24) NOT NULL,
  `headtag_id` int(10) unsigned DEFAULT NULL,
  `gangtag_id` int(10) unsigned DEFAULT NULL,
  `chat_tag_id` int(10) unsigned DEFAULT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`discord_id`),
  KEY `fk_selected_head` (`headtag_id`),
  KEY `fk_selected_gang` (`gangtag_id`),
  KEY `selected_chat_tag` (`chat_tag_id`),
  CONSTRAINT `fk_selected_chat_tag` FOREIGN KEY (`chat_tag_id`) REFERENCES `headtags` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_selected_gang` FOREIGN KEY (`gangtag_id`) REFERENCES `headtags` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_selected_head` FOREIGN KEY (`headtag_id`) REFERENCES `headtags` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `portal_sessions`;
CREATE TABLE `portal_sessions` (
  `session_hash` char(64) NOT NULL,
  `discord_id` varchar(24) NOT NULL,
  `username` varchar(100) NOT NULL,
  `avatar` varchar(300) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  `last_seen` bigint(20) NOT NULL,
  `expires_at` bigint(20) NOT NULL,
  PRIMARY KEY (`session_hash`),
  KEY `portal_session_user` (`discord_id`,`expires_at`),
  KEY `portal_session_expiry` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `property_doors`;
CREATE TABLE `property_doors` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `property_key` varchar(40) NOT NULL,
  `kind` varchar(8) NOT NULL DEFAULT 'include',
  `model` bigint(20) NOT NULL,
  `x` double NOT NULL,
  `y` double NOT NULL,
  `z` double NOT NULL,
  `added_by` varchar(24) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `property_door_key` (`property_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `property_points`;
CREATE TABLE `property_points` (
  `property_key` varchar(40) NOT NULL,
  `point` varchar(12) NOT NULL,
  `x` double NOT NULL,
  `y` double NOT NULL,
  `z` double NOT NULL,
  `set_by` varchar(24) DEFAULT NULL,
  `set_at` bigint(20) NOT NULL,
  PRIMARY KEY (`property_key`,`point`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `protected_roles`;
CREATE TABLE `protected_roles` (
  `guild_id` varchar(24) NOT NULL,
  `role_id` varchar(24) NOT NULL,
  `added_by` varchar(24) NOT NULL,
  `added_at` bigint(20) NOT NULL,
  PRIMARY KEY (`guild_id`,`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `protected_role_access`;
CREATE TABLE `protected_role_access` (
  `guild_id` varchar(24) NOT NULL,
  `role_id` varchar(24) NOT NULL,
  `subject_type` enum('user','role') NOT NULL,
  `subject_id` varchar(24) NOT NULL,
  `added_by` varchar(24) NOT NULL,
  PRIMARY KEY (`guild_id`,`role_id`,`subject_type`,`subject_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `radio_channels`;
CREATE TABLE `radio_channels` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `channel` decimal(5,2) unsigned NOT NULL,
  `name` varchar(80) NOT NULL,
  `description` varchar(180) DEFAULT NULL,
  `color` char(7) NOT NULL DEFAULT '#43E8D8',
  `org_id` int(10) unsigned DEFAULT NULL,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` varchar(32) DEFAULT NULL,
  `created_at` bigint(20) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `radio_channel_number` (`channel`),
  KEY `radio_channel_org` (`org_id`,`enabled`,`sort_order`),
  CONSTRAINT `fk_radio_channel_org` FOREIGN KEY (`org_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `role_manager_members`;
CREATE TABLE `role_manager_members` (
  `guild_id` varchar(32) NOT NULL,
  `role_id` varchar(32) NOT NULL,
  `discord_id` varchar(32) NOT NULL,
  `added_by` varchar(32) NOT NULL,
  `added_at` bigint(20) NOT NULL,
  PRIMARY KEY (`guild_id`,`role_id`,`discord_id`),
  KEY `role_manager_member` (`guild_id`,`discord_id`),
  CONSTRAINT `role_manager_members_role_fk` FOREIGN KEY (`guild_id`, `role_id`) REFERENCES `role_manager_roles` (`guild_id`, `role_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `role_manager_roles`;
CREATE TABLE `role_manager_roles` (
  `guild_id` varchar(32) NOT NULL,
  `role_id` varchar(32) NOT NULL,
  `owner_id` varchar(32) NOT NULL,
  `created_by` varchar(32) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  `updated_by` varchar(32) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`guild_id`,`role_id`),
  KEY `role_manager_owner` (`guild_id`,`owner_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `schema_migrations`;
CREATE TABLE `schema_migrations` (
  `name` varchar(100) NOT NULL,
  `applied_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `server_state`;
CREATE TABLE `server_state` (
  `key` varchar(64) NOT NULL,
  `value` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`value`)),
  `updated_by` varchar(80) DEFAULT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_accounts`;
CREATE TABLE `sky_phone_accounts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `email` varchar(64) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,
  `password` varchar(64) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_sky_phone_mail_email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_admin_audit`;
CREATE TABLE `sky_phone_admin_audit` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `actor_identifier` varchar(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `actor_name` varchar(120) NOT NULL,
  `target_identifier` varchar(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `target_source` int(10) unsigned DEFAULT NULL,
  `device_imei` char(15) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `action` varchar(48) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `details` longtext NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
