  UNIQUE KEY `uniq_sky_phone_darkchat_contact` (`profile_id`,`contact_profile_id`),
  KEY `contact_profile_id` (`contact_profile_id`),
  CONSTRAINT `sky_phone_darkchat_contacts_ibfk_1` FOREIGN KEY (`profile_id`) REFERENCES `sky_phone_darkchat_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_darkchat_contacts_ibfk_2` FOREIGN KEY (`contact_profile_id`) REFERENCES `sky_phone_darkchat_profiles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_darkchat_conversations`;
