  CONSTRAINT `sky_phone_darkchat_members_ibfk_2` FOREIGN KEY (`profile_id`) REFERENCES `sky_phone_darkchat_profiles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_darkchat_messages`;
CREATE TABLE `sky_phone_darkchat_messages` (
  `id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `conversation_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `sender_profile_id` bigint(20) unsigned DEFAULT NULL,
  `message_type` enum('text','emoji','gif','voice','image','video','share','system') NOT NULL DEFAULT 'text',
  `body` text NOT NULL,
  `media_payload` longtext DEFAULT NULL,
  `media_mime` varchar(80) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `media_duration_ms` int(10) unsigned DEFAULT NULL,
  `media_waveform` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`media_waveform`)),
  `reply_to_id` char(36) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `reactions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`reactions`)),
  `deleted_for_profiles` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`deleted_for_profiles`)),
  `deleted_for_everyone` tinyint(1) NOT NULL DEFAULT 0,
  `expires_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_sky_phone_darkchat_message_thread` (`conversation_id`,`created_at`,`id`),
  KEY `idx_sky_phone_darkchat_message_expiry` (`expires_at`),
  KEY `sender_profile_id` (`sender_profile_id`),
  CONSTRAINT `sky_phone_darkchat_messages_ibfk_1` FOREIGN KEY (`conversation_id`) REFERENCES `sky_phone_darkchat_conversations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_darkchat_messages_ibfk_2` FOREIGN KEY (`sender_profile_id`) REFERENCES `sky_phone_darkchat_profiles` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_darkchat_profiles`;
CREATE TABLE `sky_phone_darkchat_profiles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
