  CONSTRAINT `sky_phone_darkchat_reports_ibfk_1` FOREIGN KEY (`reporter_profile_id`) REFERENCES `sky_phone_darkchat_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_darkchat_reports_ibfk_2` FOREIGN KEY (`reported_profile_id`) REFERENCES `sky_phone_darkchat_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_darkchat_reports_ibfk_3` FOREIGN KEY (`conversation_id`) REFERENCES `sky_phone_darkchat_conversations` (`id`) ON DELETE SET NULL
