DROP TABLE IF EXISTS `sky_phone_flare_profiles`;
CREATE TABLE `sky_phone_flare_profiles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `account_id` bigint(20) unsigned NOT NULL,
  `name` varchar(32) NOT NULL,
  `age` tinyint(3) unsigned NOT NULL,
  `bio` varchar(300) NOT NULL DEFAULT '',
  `gender` enum('woman','man','nonbinary') NOT NULL,
  `interested_in` enum('woman','man','nonbinary','everyone') NOT NULL DEFAULT 'everyone',
  `min_age` tinyint(3) unsigned NOT NULL DEFAULT 18,
  `max_age` tinyint(3) unsigned NOT NULL DEFAULT 99,
  `avatar` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `interests` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`interests`)),
  `looking_for` enum('longTerm','dates','friends') NOT NULL DEFAULT 'longTerm',
  `discoverable` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_sky_phone_flare_profile_account` (`account_id`),
  KEY `idx_sky_phone_flare_discovery` (`gender`,`age`,`updated_at`),
  CONSTRAINT `sky_phone_flare_profiles_ibfk_1` FOREIGN KEY (`account_id`) REFERENCES `sky_phone_accounts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_flare_profile_photos`;
CREATE TABLE `sky_phone_flare_profile_photos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `profile_id` bigint(20) unsigned NOT NULL,
  `media_id` bigint(20) unsigned NOT NULL,
  `sort_order` tinyint(3) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_sky_phone_flare_photo_order` (`profile_id`,`sort_order`),
  UNIQUE KEY `uniq_sky_phone_flare_photo_media` (`profile_id`,`media_id`),
  KEY `idx_sky_phone_flare_photo_media` (`media_id`),
  CONSTRAINT `sky_phone_flare_profile_photos_ibfk_1` FOREIGN KEY (`profile_id`) REFERENCES `sky_phone_flare_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_flare_profile_photos_ibfk_2` FOREIGN KEY (`media_id`) REFERENCES `sky_phone_media` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_flare_swipes`;
CREATE TABLE `sky_phone_flare_swipes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `swiper_account_id` bigint(20) unsigned NOT NULL,
  `target_account_id` bigint(20) unsigned NOT NULL,
  `choice` enum('like','pass','superlike') NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_sky_phone_flare_swipe` (`swiper_account_id`,`target_account_id`),
  KEY `idx_sky_phone_flare_swipe_target` (`target_account_id`,`choice`),
  CONSTRAINT `sky_phone_flare_swipes_ibfk_1` FOREIGN KEY (`swiper_account_id`) REFERENCES `sky_phone_accounts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_flare_swipes_ibfk_2` FOREIGN KEY (`target_account_id`) REFERENCES `sky_phone_accounts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_fliptok_blocks`;
CREATE TABLE `sky_phone_fliptok_blocks` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `blocker_id` bigint(20) unsigned NOT NULL,
  `blocked_id` bigint(20) unsigned NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_sky_phone_fliptok_block` (`blocker_id`,`blocked_id`),
  KEY `blocked_id` (`blocked_id`),
  CONSTRAINT `sky_phone_fliptok_blocks_ibfk_1` FOREIGN KEY (`blocker_id`) REFERENCES `sky_phone_fliptok_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_fliptok_blocks_ibfk_2` FOREIGN KEY (`blocked_id`) REFERENCES `sky_phone_fliptok_profiles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_fliptok_comments`;
CREATE TABLE `sky_phone_fliptok_comments` (
  `id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `video_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `profile_id` bigint(20) unsigned NOT NULL,
  `parent_id` char(36) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `body` varchar(300) NOT NULL,
  `status` enum('visible','removed') NOT NULL DEFAULT 'visible',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_sky_phone_fliptok_comments` (`video_id`,`created_at`),
  KEY `idx_sky_phone_fliptok_comment_parent` (`parent_id`,`created_at`),
  KEY `profile_id` (`profile_id`),
  CONSTRAINT `sky_phone_fliptok_comments_ibfk_1` FOREIGN KEY (`video_id`) REFERENCES `sky_phone_fliptok_videos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_fliptok_comments_ibfk_2` FOREIGN KEY (`profile_id`) REFERENCES `sky_phone_fliptok_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_fliptok_comments_ibfk_3` FOREIGN KEY (`parent_id`) REFERENCES `sky_phone_fliptok_comments` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_fliptok_comment_reactions`;
CREATE TABLE `sky_phone_fliptok_comment_reactions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `comment_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `profile_id` bigint(20) unsigned NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_sky_phone_fliptok_comment_reaction` (`comment_id`,`profile_id`),
  KEY `profile_id` (`profile_id`),
  CONSTRAINT `sky_phone_fliptok_comment_reactions_ibfk_1` FOREIGN KEY (`comment_id`) REFERENCES `sky_phone_fliptok_comments` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_fliptok_comment_reactions_ibfk_2` FOREIGN KEY (`profile_id`) REFERENCES `sky_phone_fliptok_profiles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_fliptok_credentials`;
CREATE TABLE `sky_phone_fliptok_credentials` (
  `profile_id` bigint(20) unsigned NOT NULL,
  `password_hash` binary(32) NOT NULL,
  `password_salt` char(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`profile_id`),
  CONSTRAINT `sky_phone_fliptok_credentials_ibfk_1` FOREIGN KEY (`profile_id`) REFERENCES `sky_phone_fliptok_profiles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_fliptok_follows`;
CREATE TABLE `sky_phone_fliptok_follows` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `follower_id` bigint(20) unsigned NOT NULL,
  `following_id` bigint(20) unsigned NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_sky_phone_fliptok_follow` (`follower_id`,`following_id`),
  KEY `following_id` (`following_id`),
  CONSTRAINT `sky_phone_fliptok_follows_ibfk_1` FOREIGN KEY (`follower_id`) REFERENCES `sky_phone_fliptok_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_fliptok_follows_ibfk_2` FOREIGN KEY (`following_id`) REFERENCES `sky_phone_fliptok_profiles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_fliptok_notifications`;
CREATE TABLE `sky_phone_fliptok_notifications` (
  `id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `recipient_id` bigint(20) unsigned NOT NULL,
  `actor_id` bigint(20) unsigned NOT NULL,
  `video_id` char(36) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `kind` enum('like','comment','follow','verified') NOT NULL,
  `read_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_sky_phone_fliptok_activity` (`recipient_id`,`created_at`),
  KEY `actor_id` (`actor_id`),
  KEY `video_id` (`video_id`),
  CONSTRAINT `sky_phone_fliptok_notifications_ibfk_1` FOREIGN KEY (`recipient_id`) REFERENCES `sky_phone_fliptok_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_fliptok_notifications_ibfk_2` FOREIGN KEY (`actor_id`) REFERENCES `sky_phone_fliptok_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_fliptok_notifications_ibfk_3` FOREIGN KEY (`video_id`) REFERENCES `sky_phone_fliptok_videos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_fliptok_profiles`;
CREATE TABLE `sky_phone_fliptok_profiles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `account_id` bigint(20) unsigned NOT NULL,
  `handle` varchar(24) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,
  `display_name` varchar(40) NOT NULL,
  `bio` varchar(160) NOT NULL DEFAULT '',
  `account_type` enum('person','business','organization','media','event') NOT NULL DEFAULT 'person',
  `avatar_media_id` bigint(20) unsigned DEFAULT NULL,
  `verified` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_sky_phone_fliptok_account` (`account_id`),
  UNIQUE KEY `uniq_sky_phone_fliptok_handle` (`handle`),
  KEY `avatar_media_id` (`avatar_media_id`),
  CONSTRAINT `sky_phone_fliptok_profiles_ibfk_1` FOREIGN KEY (`account_id`) REFERENCES `sky_phone_accounts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_fliptok_profiles_ibfk_2` FOREIGN KEY (`avatar_media_id`) REFERENCES `sky_phone_media` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_fliptok_reactions`;
CREATE TABLE `sky_phone_fliptok_reactions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `video_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `profile_id` bigint(20) unsigned NOT NULL,
  `kind` enum('like','save') NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_sky_phone_fliptok_reaction` (`video_id`,`profile_id`,`kind`),
  KEY `profile_id` (`profile_id`),
  CONSTRAINT `sky_phone_fliptok_reactions_ibfk_1` FOREIGN KEY (`video_id`) REFERENCES `sky_phone_fliptok_videos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_fliptok_reactions_ibfk_2` FOREIGN KEY (`profile_id`) REFERENCES `sky_phone_fliptok_profiles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_fliptok_reports`;
CREATE TABLE `sky_phone_fliptok_reports` (
  `id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `reporter_id` bigint(20) unsigned NOT NULL,
  `video_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `reason` enum('spam','harassment','dangerous','illegal','other') NOT NULL,
  `details` varchar(500) NOT NULL DEFAULT '',
  `status` enum('open','reviewed','dismissed') NOT NULL DEFAULT 'open',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_sky_phone_fliptok_report` (`reporter_id`,`video_id`),
  KEY `video_id` (`video_id`),
  CONSTRAINT `sky_phone_fliptok_reports_ibfk_1` FOREIGN KEY (`reporter_id`) REFERENCES `sky_phone_fliptok_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_fliptok_reports_ibfk_2` FOREIGN KEY (`video_id`) REFERENCES `sky_phone_fliptok_videos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_fliptok_sessions`;
CREATE TABLE `sky_phone_fliptok_sessions` (
  `device_imei` char(15) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
