  KEY `idx_sky_phone_fliptok_sessions_profile` (`profile_id`,`updated_at`),
  CONSTRAINT `sky_phone_fliptok_sessions_ibfk_1` FOREIGN KEY (`device_imei`) REFERENCES `sky_phone_devices` (`imei`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_fliptok_sessions_ibfk_2` FOREIGN KEY (`profile_id`) REFERENCES `sky_phone_fliptok_profiles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_fliptok_videos`;
CREATE TABLE `sky_phone_fliptok_videos` (
  `id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `profile_id` bigint(20) unsigned NOT NULL,
  `media_id` bigint(20) unsigned NOT NULL,
  `caption` varchar(500) NOT NULL DEFAULT '',
  `location` varchar(80) NOT NULL DEFAULT '',
  `visibility` enum('public','followers','private') NOT NULL DEFAULT 'public',
  `comments_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `trim_start_ms` int(10) unsigned NOT NULL DEFAULT 0,
  `trim_end_ms` int(10) unsigned DEFAULT NULL,
  `cover_time_ms` int(10) unsigned NOT NULL DEFAULT 0,
  `original_volume` tinyint(3) unsigned NOT NULL DEFAULT 100,
  `music_volume` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `music_track` varchar(64) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL DEFAULT '',
  `custom_music_url` varchar(2048) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '',
  `custom_music_title` varchar(160) NOT NULL DEFAULT '',
  `custom_music_artist` varchar(120) NOT NULL DEFAULT '',
  `status` enum('draft','published','removed') NOT NULL DEFAULT 'published',
  `view_count` int(10) unsigned NOT NULL DEFAULT 0,
  `share_count` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_sky_phone_fliptok_feed` (`status`,`visibility`,`created_at`),
  KEY `idx_sky_phone_fliptok_profile` (`profile_id`,`created_at`),
  KEY `media_id` (`media_id`),
  CONSTRAINT `sky_phone_fliptok_videos_ibfk_1` FOREIGN KEY (`profile_id`) REFERENCES `sky_phone_fliptok_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_fliptok_videos_ibfk_2` FOREIGN KEY (`media_id`) REFERENCES `sky_phone_media` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_fliptok_video_media`;
CREATE TABLE `sky_phone_fliptok_video_media` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `video_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `media_id` bigint(20) unsigned NOT NULL,
