  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_sky_phone_fliptok_video_media_order` (`video_id`,`sort_order`),
  UNIQUE KEY `uniq_sky_phone_fliptok_video_media` (`video_id`,`media_id`),
  KEY `media_id` (`media_id`),
  CONSTRAINT `sky_phone_fliptok_video_media_ibfk_1` FOREIGN KEY (`video_id`) REFERENCES `sky_phone_fliptok_videos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_fliptok_video_media_ibfk_2` FOREIGN KEY (`media_id`) REFERENCES `sky_phone_media` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_health_daily`;
CREATE TABLE `sky_phone_health_daily` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `owner_identifier` varchar(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
