  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_sky_phone_health_daily` (`owner_identifier`,`activity_date`),
  KEY `idx_sky_phone_health_history` (`owner_identifier`,`activity_date`)
) ENGINE=InnoDB AUTO_INCREMENT=4311 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_health_profiles`;
CREATE TABLE `sky_phone_health_profiles` (
