  KEY `reserved_account_id` (`reserved_account_id`),
  CONSTRAINT `sky_phone_marketplace_listings_ibfk_1` FOREIGN KEY (`seller_account_id`) REFERENCES `sky_phone_accounts` (`id`) ON DELETE CASCADE,
