  `bio` varchar(160) NOT NULL DEFAULT '',
  `avatar_media_id` bigint(20) unsigned DEFAULT NULL,
  `avatar_seed` int(10) unsigned NOT NULL DEFAULT 1,
  `story_privacy` enum('friends','everyone') NOT NULL DEFAULT 'friends',
  `quick_add` tinyint(1) NOT NULL DEFAULT 1,
  `allow_story_replies` tinyint(1) NOT NULL DEFAULT 1,
  `snap_score` bigint(20) unsigned NOT NULL DEFAULT 0,
  `friend_count` int(10) unsigned NOT NULL DEFAULT 0,
  `status` enum('active','hidden','removed') NOT NULL DEFAULT 'active',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_sky_phone_skypic_profile_account` (`account_id`),
  UNIQUE KEY `uniq_sky_phone_skypic_profile_handle` (`handle`),
  KEY `idx_sky_phone_skypic_quick_add` (`status`,`quick_add`,`updated_at`),
  KEY `avatar_media_id` (`avatar_media_id`),
  CONSTRAINT `sky_phone_skypic_profiles_ibfk_1` FOREIGN KEY (`account_id`) REFERENCES `sky_phone_accounts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_skypic_profiles_ibfk_2` FOREIGN KEY (`avatar_media_id`) REFERENCES `sky_phone_media` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_skypic_spotlights`;
CREATE TABLE `sky_phone_skypic_spotlights` (
  `id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `profile_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `media_id` bigint(20) unsigned NOT NULL,
  `caption` varchar(160) NOT NULL DEFAULT '',
  `overlay_text` varchar(160) NOT NULL DEFAULT '',
  `overlay_color` char(7) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '#FFFFFF',
  `kind` enum('organic','sponsored') NOT NULL DEFAULT 'organic',
  `ad_headline` varchar(80) NOT NULL DEFAULT '',
  `comments_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `status` enum('active','removed') NOT NULL DEFAULT 'active',
  `expires_at` datetime(6) NOT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  PRIMARY KEY (`id`),
  KEY `idx_sky_phone_skypic_spotlight_feed` (`status`,`created_at`,`id`),
  KEY `idx_sky_phone_skypic_spotlight_profile` (`profile_id`,`status`,`created_at`),
  KEY `idx_sky_phone_skypic_spotlight_expiry` (`status`,`expires_at`),
  KEY `idx_sky_phone_skypic_spotlight_media` (`media_id`),
  CONSTRAINT `sky_phone_skypic_spotlights_ibfk_1` FOREIGN KEY (`profile_id`) REFERENCES `sky_phone_skypic_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_skypic_spotlights_ibfk_2` FOREIGN KEY (`media_id`) REFERENCES `sky_phone_media` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_skypic_spotlight_comments`;
CREATE TABLE `sky_phone_skypic_spotlight_comments` (
  `id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `spotlight_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `profile_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `body` varchar(500) NOT NULL,
  `status` enum('visible','removed') NOT NULL DEFAULT 'visible',
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  PRIMARY KEY (`id`),
  KEY `idx_sky_phone_skypic_spotlight_comments` (`spotlight_id`,`status`,`created_at`,`id`),
  KEY `idx_sky_phone_skypic_spotlight_comment_author` (`profile_id`,`created_at`),
  CONSTRAINT `sky_phone_skypic_spotlight_comments_ibfk_1` FOREIGN KEY (`spotlight_id`) REFERENCES `sky_phone_skypic_spotlights` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_skypic_spotlight_comments_ibfk_2` FOREIGN KEY (`profile_id`) REFERENCES `sky_phone_skypic_profiles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_skypic_spotlight_likes`;
CREATE TABLE `sky_phone_skypic_spotlight_likes` (
  `spotlight_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `profile_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  PRIMARY KEY (`spotlight_id`,`profile_id`),
  KEY `idx_sky_phone_skypic_spotlight_liker` (`profile_id`,`created_at`),
  CONSTRAINT `sky_phone_skypic_spotlight_likes_ibfk_1` FOREIGN KEY (`spotlight_id`) REFERENCES `sky_phone_skypic_spotlights` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_skypic_spotlight_likes_ibfk_2` FOREIGN KEY (`profile_id`) REFERENCES `sky_phone_skypic_profiles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_skypic_spotlight_reports`;
CREATE TABLE `sky_phone_skypic_spotlight_reports` (
  `spotlight_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `reporter_profile_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `reason` varchar(32) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,
  `details` varchar(500) NOT NULL DEFAULT '',
  `status` enum('pending','reviewed','dismissed') NOT NULL DEFAULT 'pending',
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  PRIMARY KEY (`spotlight_id`,`reporter_profile_id`),
  KEY `idx_sky_phone_skypic_spotlight_report_queue` (`status`,`created_at`),
  KEY `reporter_profile_id` (`reporter_profile_id`),
  CONSTRAINT `sky_phone_skypic_spotlight_reports_ibfk_1` FOREIGN KEY (`spotlight_id`) REFERENCES `sky_phone_skypic_spotlights` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_skypic_spotlight_reports_ibfk_2` FOREIGN KEY (`reporter_profile_id`) REFERENCES `sky_phone_skypic_profiles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_skypic_spotlight_views`;
CREATE TABLE `sky_phone_skypic_spotlight_views` (
  `spotlight_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `viewer_profile_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `viewed_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  PRIMARY KEY (`spotlight_id`,`viewer_profile_id`),
  KEY `idx_sky_phone_skypic_spotlight_viewer` (`viewer_profile_id`,`viewed_at`),
  CONSTRAINT `sky_phone_skypic_spotlight_views_ibfk_1` FOREIGN KEY (`spotlight_id`) REFERENCES `sky_phone_skypic_spotlights` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_skypic_spotlight_views_ibfk_2` FOREIGN KEY (`viewer_profile_id`) REFERENCES `sky_phone_skypic_profiles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_skypic_stories`;
CREATE TABLE `sky_phone_skypic_stories` (
  `id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `profile_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `media_id` bigint(20) unsigned NOT NULL,
  `caption` varchar(160) NOT NULL DEFAULT '',
  `overlay_text` varchar(160) NOT NULL DEFAULT '',
  `overlay_color` char(7) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '#FFFFFF',
  `view_seconds` tinyint(3) unsigned NOT NULL,
  `privacy` enum('friends','everyone') NOT NULL,
  `status` enum('active','removed') NOT NULL DEFAULT 'active',
  `expires_at` datetime(6) NOT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  PRIMARY KEY (`id`),
  KEY `idx_sky_phone_skypic_story_profile` (`profile_id`,`status`,`expires_at`),
  KEY `idx_sky_phone_skypic_story_expiry` (`status`,`expires_at`),
  KEY `idx_sky_phone_skypic_story_media` (`media_id`),
  CONSTRAINT `sky_phone_skypic_stories_ibfk_1` FOREIGN KEY (`profile_id`) REFERENCES `sky_phone_skypic_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_skypic_stories_ibfk_2` FOREIGN KEY (`media_id`) REFERENCES `sky_phone_media` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_skypic_story_views`;
CREATE TABLE `sky_phone_skypic_story_views` (
  `story_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `viewer_profile_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `viewed_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  PRIMARY KEY (`story_id`,`viewer_profile_id`),
  KEY `idx_sky_phone_skypic_story_viewer` (`viewer_profile_id`,`viewed_at`),
  CONSTRAINT `sky_phone_skypic_story_views_ibfk_1` FOREIGN KEY (`story_id`) REFERENCES `sky_phone_skypic_stories` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_skypic_story_views_ibfk_2` FOREIGN KEY (`viewer_profile_id`) REFERENCES `sky_phone_skypic_profiles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_skyride_profiles`;
CREATE TABLE `sky_phone_skyride_profiles` (
  `id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `owner_identifier` varchar(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `display_name` varchar(50) DEFAULT NULL,
  `avatar_media_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_sky_phone_skyride_owner` (`owner_identifier`),
  KEY `idx_sky_phone_skyride_profile_avatar` (`avatar_media_id`),
  CONSTRAINT `sky_phone_skyride_profiles_ibfk_1` FOREIGN KEY (`avatar_media_id`) REFERENCES `sky_phone_media` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_skyride_rides`;
CREATE TABLE `sky_phone_skyride_rides` (
  `id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `passenger_profile_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `driver_profile_id` char(36) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `passenger_name` varchar(80) NOT NULL,
  `driver_name` varchar(80) DEFAULT NULL,
  `status` enum('payment_pending','searching','accepted','arrived','in_progress','completing','completed','cancelled') NOT NULL,
  `service_class` enum('taxi','comfort','xl','premium') NOT NULL,
  `pickup_label` varchar(80) NOT NULL,
  `pickup_x` decimal(10,3) NOT NULL,
  `pickup_y` decimal(10,3) NOT NULL,
  `pickup_z` decimal(10,3) NOT NULL,
  `destination_label` varchar(80) NOT NULL,
  `destination_x` decimal(10,3) NOT NULL,
  `destination_y` decimal(10,3) NOT NULL,
  `destination_z` decimal(10,3) NOT NULL,
  `distance_meters` int(10) unsigned NOT NULL,
  `duration_seconds` int(10) unsigned NOT NULL,
  `price` int(10) unsigned NOT NULL,
  `payout_amount` int(10) unsigned NOT NULL,
  `currency` varchar(8) NOT NULL,
  `driver_vehicle_model` varchar(64) DEFAULT NULL,
  `driver_vehicle_color` varchar(64) DEFAULT NULL,
  `driver_vehicle_plate` varchar(16) DEFAULT NULL,
  `cancelled_by` enum('passenger','driver','system') DEFAULT NULL,
  `cancel_reason` varchar(32) DEFAULT NULL,
  `passenger_rating` tinyint(3) unsigned DEFAULT NULL,
  `rating_comment` varchar(300) DEFAULT NULL,
  `tip_amount` int(10) unsigned NOT NULL DEFAULT 0,
  `refund_status` enum('none','pending','processing','completed') NOT NULL DEFAULT 'none',
  `tip_status` enum('none','processing','completed','failed') NOT NULL DEFAULT 'none',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `accepted_at` datetime DEFAULT NULL,
  `arrived_at` datetime DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `refunded_at` datetime DEFAULT NULL,
  `paid_out_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_sky_phone_skyride_passenger` (`passenger_profile_id`,`status`,`updated_at`),
  KEY `idx_sky_phone_skyride_driver` (`driver_profile_id`,`status`,`updated_at`),
  KEY `idx_sky_phone_skyride_requests` (`status`,`created_at`),
  KEY `idx_sky_phone_skyride_refunds` (`refund_status`,`status`,`updated_at`),
  CONSTRAINT `sky_phone_skyride_rides_ibfk_1` FOREIGN KEY (`passenger_profile_id`) REFERENCES `sky_phone_skyride_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_skyride_rides_ibfk_2` FOREIGN KEY (`driver_profile_id`) REFERENCES `sky_phone_skyride_profiles` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_sms_messages`;
CREATE TABLE `sky_phone_sms_messages` (
  `id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `sender_sim_id` char(36) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `recipient_sim_id` char(36) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `sender_number` varchar(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `recipient_number` varchar(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `message_type` enum('text','voice','image','gif','video','contact','share') NOT NULL DEFAULT 'text',
  `body` varchar(2000) NOT NULL,
  `media_payload` mediumtext DEFAULT NULL,
  `media_mime` varchar(64) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL,
  `media_duration_ms` int(10) unsigned DEFAULT NULL,
  `media_waveform` text DEFAULT NULL,
  `read_at` datetime DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  PRIMARY KEY (`id`),
  KEY `idx_sky_phone_sms_sender` (`sender_sim_id`,`created_at`),
  KEY `idx_sky_phone_sms_recipient` (`recipient_sim_id`,`created_at`),
  CONSTRAINT `sky_phone_sms_messages_ibfk_1` FOREIGN KEY (`sender_sim_id`) REFERENCES `sky_phone_sims` (`id`) ON DELETE SET NULL,
  CONSTRAINT `sky_phone_sms_messages_ibfk_2` FOREIGN KEY (`recipient_sim_id`) REFERENCES `sky_phone_sims` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_voice_memos`;
CREATE TABLE `sky_phone_voice_memos` (
  `id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `media_id` bigint(20) unsigned NOT NULL,
  `title` varchar(120) NOT NULL,
  `note` varchar(2000) NOT NULL DEFAULT '',
  `duration_ms` int(10) unsigned NOT NULL,
  `size_bytes` int(10) unsigned NOT NULL,
  `waveform` text NOT NULL,
  `pinned` tinyint(1) NOT NULL DEFAULT 0,
  `revision` int(10) unsigned NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_sky_phone_voice_memos_media` (`media_id`),
  KEY `idx_sky_phone_voice_memos_list` (`pinned`,`updated_at`,`id`),
  CONSTRAINT `sky_phone_voice_memos_ibfk_1` FOREIGN KEY (`media_id`) REFERENCES `sky_phone_media` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_weazel_articles`;
CREATE TABLE `sky_phone_weazel_articles` (
  `id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `title` varchar(160) NOT NULL,
  `body` longtext NOT NULL,
  `excerpt` varchar(240) NOT NULL,
  `category` enum('official','events','jobs','news','business') NOT NULL,
  `image_media_id` bigint(20) unsigned DEFAULT NULL,
  `author_identifier` varchar(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `author_name` varchar(120) NOT NULL,
  `updated_by_identifier` varchar(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `status` enum('draft','published') NOT NULL DEFAULT 'draft',
  `revision` int(10) unsigned NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `published_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by_identifier` varchar(80) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_sky_phone_weazel_public` (`status`,`deleted_at`,`published_at`,`id`),
  KEY `idx_sky_phone_weazel_category` (`category`,`status`,`deleted_at`,`published_at`,`id`),
  KEY `idx_sky_phone_weazel_manage` (`deleted_at`,`status`,`updated_at`,`id`),
  KEY `idx_sky_phone_weazel_media` (`image_media_id`),
  CONSTRAINT `sky_phone_weazel_articles_ibfk_1` FOREIGN KEY (`image_media_id`) REFERENCES `sky_phone_media` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_weazel_article_media`;
CREATE TABLE `sky_phone_weazel_article_media` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `article_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `media_id` bigint(20) unsigned NOT NULL,
  `position` tinyint(3) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_sky_phone_weazel_article_position` (`article_id`,`position`),
  UNIQUE KEY `uniq_sky_phone_weazel_article_media` (`article_id`,`media_id`),
  KEY `media_id` (`media_id`),
  CONSTRAINT `sky_phone_weazel_article_media_ibfk_1` FOREIGN KEY (`article_id`) REFERENCES `sky_phone_weazel_articles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sky_phone_weazel_article_media_ibfk_2` FOREIGN KEY (`media_id`) REFERENCES `sky_phone_media` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sky_phone_webhooks`;
CREATE TABLE `sky_phone_webhooks` (
  `id` tinyint(3) unsigned NOT NULL,
  `payload` longtext NOT NULL,
  `revision` int(10) unsigned NOT NULL DEFAULT 0,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `staff_exams`;
CREATE TABLE `staff_exams` (
  `exam_key` varchar(32) NOT NULL,
  `title` varchar(80) NOT NULL,
  `target_rank` varchar(80) NOT NULL,
  `eligible_group` varchar(64) NOT NULL,
  `description` varchar(600) NOT NULL DEFAULT '',
  `pass_role_name` varchar(80) NOT NULL,
  `pass_role_id` varchar(24) DEFAULT NULL,
  `questions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`questions`)),
  `pass_mark` int(10) unsigned NOT NULL DEFAULT 70,
  `cooldown_days` int(10) unsigned NOT NULL DEFAULT 14,
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `updated_at` bigint(20) NOT NULL DEFAULT 0,
  PRIMARY KEY (`exam_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `staff_exam_applications`;
CREATE TABLE `staff_exam_applications` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `exam_key` varchar(32) NOT NULL,
  `discord_id` varchar(24) NOT NULL,
  `display_name` varchar(100) NOT NULL DEFAULT '',
  `rank_at_submit` varchar(80) NOT NULL DEFAULT '',
  `answers` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`answers`)),
  `auto_score` int(11) DEFAULT NULL,
  `status` enum('submitted','under_review','passed','failed','withdrawn') NOT NULL DEFAULT 'submitted',
  `score` int(11) DEFAULT NULL,
  `reviewer_id` varchar(24) DEFAULT NULL,
  `review_notes` varchar(2000) DEFAULT NULL,
  `role_granted` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` bigint(20) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  `reviewed_at` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `exam_app_status` (`exam_key`,`status`,`created_at`),
  KEY `exam_app_member` (`discord_id`,`exam_key`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `staff_exam_grants`;
CREATE TABLE `staff_exam_grants` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `exam_key` varchar(32) NOT NULL,
  `discord_id` varchar(24) NOT NULL,
  `granted_by` varchar(24) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  `expires_at` bigint(20) NOT NULL,
  `used_at` bigint(20) DEFAULT NULL,
  `revoked_at` bigint(20) DEFAULT NULL,
  `revoked_by` varchar(24) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `exam_grant_member` (`discord_id`,`exam_key`,`expires_at`),
  KEY `exam_grant_active` (`expires_at`,`used_at`,`revoked_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `staff_handoff_notes`;
CREATE TABLE `staff_handoff_notes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `author_id` varchar(32) NOT NULL,
  `body` varchar(1000) NOT NULL,
  `pinned` tinyint(1) NOT NULL DEFAULT 0,
  `resolved_at` bigint(20) DEFAULT NULL,
  `resolved_by` varchar(32) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `handoff_open` (`resolved_at`,`pinned`,`created_at`),
  KEY `handoff_author` (`author_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `staff_roster_categories`;
CREATE TABLE `staff_roster_categories` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(80) NOT NULL,
  `callsign_start` int(10) unsigned NOT NULL,
  `callsign_end` int(10) unsigned NOT NULL,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `roster_category_name` (`name`),
  UNIQUE KEY `roster_category_range` (`callsign_start`,`callsign_end`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `staff_roster_discipline`;
CREATE TABLE `staff_roster_discipline` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `discord_id` varchar(24) NOT NULL,
  `kind` enum('warning','strike') NOT NULL,
  `reason` varchar(500) NOT NULL,
  `actor_id` varchar(24) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  `revoked_at` bigint(20) DEFAULT NULL,
  `revoked_by` varchar(24) DEFAULT NULL,
  `revoke_reason` varchar(300) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `roster_discipline_member` (`discord_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `staff_roster_history`;
CREATE TABLE `staff_roster_history` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `discord_id` varchar(24) NOT NULL,
  `action` varchar(40) NOT NULL,
  `actor_id` varchar(24) NOT NULL,
  `details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`details`)),
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `roster_history_member` (`discord_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=446 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `staff_roster_jobs`;
CREATE TABLE `staff_roster_jobs` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(80) NOT NULL,
  `description` varchar(300) NOT NULL DEFAULT '',
  `discord_role_id` varchar(24) DEFAULT NULL,
  `discord_guild_id` varchar(24) DEFAULT NULL,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `staff_job_name` (`name`),
  KEY `staff_job_role` (`discord_guild_id`,`discord_role_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `staff_roster_members`;
CREATE TABLE `staff_roster_members` (
  `discord_id` varchar(24) NOT NULL,
  `display_name` varchar(80) NOT NULL DEFAULT '',
  `username` varchar(80) NOT NULL DEFAULT '',
  `rank_name` varchar(80) NOT NULL,
  `rank_id` int(10) unsigned DEFAULT NULL,
  `callsign` int(10) unsigned DEFAULT NULL,
  `status` enum('active','inactive','loa','removed') NOT NULL DEFAULT 'active',
  `joined_at` bigint(20) NOT NULL,
  `rank_changed_at` bigint(20) NOT NULL DEFAULT 0,
  `tickets_handled` int(10) unsigned NOT NULL DEFAULT 0,
  `activity_note` varchar(500) NOT NULL DEFAULT '',
  `updated_at` bigint(20) NOT NULL,
  `added_by` varchar(24) NOT NULL,
  `removed_at` bigint(20) DEFAULT NULL,
  `removed_by` varchar(24) DEFAULT NULL,
  `removal_reason` varchar(300) DEFAULT NULL,
  PRIMARY KEY (`discord_id`),
  UNIQUE KEY `callsign` (`callsign`),
  KEY `roster_rank_status` (`rank_name`,`status`),
  KEY `roster_rank_id` (`rank_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `staff_roster_member_jobs`;
CREATE TABLE `staff_roster_member_jobs` (
  `discord_id` varchar(24) NOT NULL,
  `job_id` int(10) unsigned NOT NULL,
  `assigned_by` varchar(24) NOT NULL,
  `assigned_at` bigint(20) NOT NULL,
  PRIMARY KEY (`discord_id`,`job_id`),
  KEY `staff_job_members` (`job_id`,`discord_id`),
  CONSTRAINT `fk_staff_job` FOREIGN KEY (`job_id`) REFERENCES `staff_roster_jobs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_staff_job_member` FOREIGN KEY (`discord_id`) REFERENCES `staff_roster_members` (`discord_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `staff_roster_ranks`;
CREATE TABLE `staff_roster_ranks` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `category_id` int(10) unsigned NOT NULL,
  `name` varchar(80) NOT NULL,
  `discord_role_id` varchar(24) DEFAULT NULL,
  `discord_guild_id` varchar(24) DEFAULT NULL,
  `ace_group` varchar(64) DEFAULT NULL,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `weekly_seconds` int(10) unsigned NOT NULL DEFAULT 0,
  `minimum_days` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `roster_rank_name` (`name`),
  KEY `roster_rank_role` (`discord_guild_id`,`discord_role_id`),
  KEY `fk_roster_rank_category` (`category_id`),
  KEY `fk_roster_rank_ace_group` (`ace_group`),
  CONSTRAINT `fk_roster_rank_ace_group` FOREIGN KEY (`ace_group`) REFERENCES `ace_groups` (`name`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_roster_rank_category` FOREIGN KEY (`category_id`) REFERENCES `staff_roster_categories` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `staff_shifts`;
CREATE TABLE `staff_shifts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `discord_id` varchar(24) NOT NULL,
  `player_id` int(10) unsigned DEFAULT NULL,
  `name` varchar(80) NOT NULL,
  `started_at` bigint(20) NOT NULL,
  `ended_at` bigint(20) DEFAULT NULL,
  `heartbeat_at` bigint(20) NOT NULL,
  `seconds` int(10) unsigned NOT NULL DEFAULT 0,
  `end_reason` varchar(24) DEFAULT NULL,
  `actor_id` varchar(24) DEFAULT NULL,
  `note` varchar(200) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `staff_shift_member` (`discord_id`,`started_at`),
  KEY `staff_shift_open` (`ended_at`)
) ENGINE=InnoDB AUTO_INCREMENT=486 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `staff_welcome_queue`;
CREATE TABLE `staff_welcome_queue` (
  `discord_id` varchar(24) NOT NULL,
  `rank_name` varchar(80) NOT NULL,
  `callsign` varchar(24) NOT NULL,
  `staff_only` tinyint(1) NOT NULL DEFAULT 0,
  `requested_by` varchar(32) NOT NULL,
  `requested_at` bigint(20) NOT NULL,
  `attempts` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`discord_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `station_doors`;
CREATE TABLE `station_doors` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `station` varchar(60) NOT NULL,
  `model` bigint(20) NOT NULL,
  `x` double NOT NULL,
  `y` double NOT NULL,
  `z` double NOT NULL,
  `added_by` varchar(32) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  `access` varchar(20) NOT NULL DEFAULT 'leo',
  PRIMARY KEY (`id`),
  KEY `station_door_station` (`station`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `support_tickets`;
CREATE TABLE `support_tickets` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `guild_id` varchar(24) NOT NULL,
  `channel_id` varchar(24) DEFAULT NULL,
  `author_id` varchar(24) NOT NULL,
  `subject` varchar(120) NOT NULL,
  `status` enum('open','claimed','closed') NOT NULL DEFAULT 'open',
  `claimed_by` varchar(24) DEFAULT NULL,
  `created_at` bigint(20) NOT NULL,
  `closed_at` bigint(20) DEFAULT NULL,
  `type` varchar(24) NOT NULL DEFAULT 'support',
  `form_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`form_data`)),
  `priority` tinyint(4) NOT NULL DEFAULT 3,
  `due_at` bigint(20) DEFAULT NULL,
  `claimed_at` bigint(20) DEFAULT NULL,
  `first_response_at` bigint(20) DEFAULT NULL,
  `closed_by` varchar(24) DEFAULT NULL,
  `close_reason` varchar(500) DEFAULT NULL,
  `close_requested_by` varchar(24) DEFAULT NULL,
  `close_requested_at` bigint(20) DEFAULT NULL,
  `reopen_count` int(11) NOT NULL DEFAULT 0,
  `last_activity` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `channel_id` (`channel_id`),
  KEY `ticket_queue` (`guild_id`,`status`,`created_at`),
  KEY `ticket_author` (`author_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tebex_store_entitlements`;
CREATE TABLE `tebex_store_entitlements` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `source_key` varchar(190) NOT NULL,
  `transaction_id` varchar(80) NOT NULL,
  `recurring_reference` varchar(80) DEFAULT NULL,
  `product_id` varchar(80) DEFAULT NULL,
  `product_name` varchar(160) NOT NULL,
  `discord_id` varchar(24) NOT NULL,
  `role_id` varchar(24) NOT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `granted_at` bigint(20) NOT NULL,
  `revoked_at` bigint(20) DEFAULT NULL,
  `last_webhook_id` varchar(64) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `tebex_entitlement_source_role` (`source_key`,`role_id`),
  KEY `tebex_entitlement_member_role` (`discord_id`,`role_id`,`active`),
  KEY `tebex_entitlement_recurring` (`recurring_reference`,`active`),
  KEY `tebex_entitlement_transaction` (`transaction_id`)
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

DROP TABLE IF EXISTS `tebex_store_role_states`;
CREATE TABLE `tebex_store_role_states` (
  `discord_id` varchar(24) NOT NULL,
  `role_id` varchar(24) NOT NULL,
  `bot_managed` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` bigint(20) NOT NULL,
  `updated_at` bigint(20) NOT NULL,
  PRIMARY KEY (`discord_id`,`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

DROP TABLE IF EXISTS `tebex_webhook_events`;
CREATE TABLE `tebex_webhook_events` (
  `webhook_id` varchar(64) NOT NULL,
  `event_type` varchar(64) NOT NULL,
  `status` enum('processing','done','attention','failed') NOT NULL,
  `payload` mediumtext NOT NULL,
  `error` varchar(500) DEFAULT NULL,
  `received_at` bigint(20) NOT NULL,
  `processed_at` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`webhook_id`),
  KEY `tebex_webhook_status` (`status`,`received_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

DROP TABLE IF EXISTS `temporary_discord_roles`;
CREATE TABLE `temporary_discord_roles` (
  `guild_id` varchar(32) NOT NULL,
  `member_id` varchar(32) NOT NULL,
  `role_id` varchar(32) NOT NULL,
  `granted_by` varchar(32) NOT NULL,
  `reason` varchar(300) NOT NULL,
  `granted_at` bigint(20) NOT NULL,
  `expires_at` bigint(20) NOT NULL,
  `status` enum('active','expiring','expired') NOT NULL DEFAULT 'active',
  `removed_at` bigint(20) DEFAULT NULL,
  `removal_error` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`guild_id`,`member_id`,`role_id`),
  KEY `idx_temporary_discord_roles_expiry` (`status`,`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ticket_events`;
CREATE TABLE `ticket_events` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `ticket_id` bigint(20) unsigned DEFAULT NULL,
  `guild_id` varchar(24) NOT NULL,
  `event_type` varchar(40) NOT NULL,
  `actor_id` varchar(24) DEFAULT NULL,
  `detail` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`detail`)),
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ticket_event_lookup` (`ticket_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=279 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ticket_notes`;
CREATE TABLE `ticket_notes` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `ticket_id` bigint(20) unsigned NOT NULL,
  `author_id` varchar(24) NOT NULL,
  `body` text NOT NULL,
  `created_at` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ticket_notes_lookup` (`ticket_id`,`created_at`),
  CONSTRAINT `fk_ticket_note` FOREIGN KEY (`ticket_id`) REFERENCES `support_tickets` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ticket_participants`;
CREATE TABLE `ticket_participants` (
  `ticket_id` bigint(20) unsigned NOT NULL,
  `user_id` varchar(24) NOT NULL,
  `added_by` varchar(24) DEFAULT NULL,
  `added_at` bigint(20) NOT NULL,
  PRIMARY KEY (`ticket_id`,`user_id`),
  CONSTRAINT `fk_ticket_participant` FOREIGN KEY (`ticket_id`) REFERENCES `support_tickets` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ticket_priorities`;
CREATE TABLE `ticket_priorities` (
  `level` tinyint(3) unsigned NOT NULL,
  `label` varchar(40) NOT NULL,
  `sla_minutes` int(10) unsigned NOT NULL DEFAULT 240,
  PRIMARY KEY (`level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ticket_settings`;
CREATE TABLE `ticket_settings` (
  `guild_id` varchar(24) NOT NULL,
  `key` varchar(64) NOT NULL,
  `value` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`value`)),
  PRIMARY KEY (`guild_id`,`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ticket_support_roles`;
CREATE TABLE `ticket_support_roles` (
  `guild_id` varchar(24) NOT NULL,
  `ticket_type` varchar(24) NOT NULL,
  `role_id` varchar(24) NOT NULL,
  `level` enum('support','manager') NOT NULL DEFAULT 'support',
  PRIMARY KEY (`guild_id`,`ticket_type`,`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ticket_transcripts`;
CREATE TABLE `ticket_transcripts` (
  `ticket_id` bigint(20) unsigned NOT NULL,
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`content`)),
  `message_count` int(10) unsigned NOT NULL DEFAULT 0,
  `generated_at` bigint(20) NOT NULL,
  `generated_by` varchar(32) NOT NULL,
  `revision` int(10) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`ticket_id`),
  KEY `transcript_generated` (`generated_at`),
  CONSTRAINT `fk_transcript_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `support_tickets` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ticket_types`;
CREATE TABLE `ticket_types` (
  `type_key` varchar(24) NOT NULL,
  `label` varchar(100) NOT NULL,
  `description` varchar(100) NOT NULL DEFAULT '',
  `priority` tinyint(3) unsigned NOT NULL DEFAULT 3,
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `fields` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`fields`)),
  PRIMARY KEY (`type_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `vehicle_registrations`;
CREATE TABLE `vehicle_registrations` (
  `plate` varchar(8) NOT NULL,
  `model` varchar(40) NOT NULL,
  `label` varchar(60) DEFAULT NULL,
  `character_id` bigint(20) unsigned DEFAULT NULL,
  `owner_name` varchar(100) NOT NULL,
  `license` varchar(100) DEFAULT NULL,
  `discord_id` varchar(32) DEFAULT NULL,
  `stolen` tinyint(1) NOT NULL DEFAULT 0,
  `impounded_at` bigint(20) DEFAULT NULL,
  `impounded_by` varchar(100) DEFAULT NULL,
  `registered_at` bigint(20) NOT NULL,
  PRIMARY KEY (`plate`),
  KEY `registration_character` (`character_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `warrants`;
CREATE TABLE `warrants` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `character_id` bigint(20) unsigned DEFAULT NULL,
  `subject_name` varchar(100) NOT NULL,
  `reason` varchar(500) NOT NULL,
  `status` enum('active','served','cleared') NOT NULL DEFAULT 'active',
  `created_by_id` varchar(32) DEFAULT NULL,
  `created_by` varchar(100) NOT NULL,
  `created_at` bigint(20) NOT NULL,
  `closed_by` varchar(100) DEFAULT NULL,
  `closed_at` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `warrant_character` (`character_id`,`status`),
  KEY `warrant_status` (`status`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS=1;
SET UNIQUE_CHECKS=1;
