INSERT INTO `dev_submissions` (`id`,`repo`,`branch`,`before_sha`,`head_sha`,`pusher`,`commit_count`,`title`,`compare_url`,`status`,`risk`,`static_risk`,`ai_model`,`analysis`,`flags`,`files`,`diff_excerpt`,`analysis_error`,`notified_at`,`decided_by`,`decided_at`,`decision_note`,`agent`,`run_started_at`,`run_finished_at`,`run_exit`,`run_log_path`,`result_summary`,`result_notified_at`,`created_at`,`updated_at`) VALUES
(1,'phinton1027/fbrp-saif-dev','main','anon_c8279347e00976b52fb2','anon_43b03df6bb51ac8ef9db','phinton1027',1,'Test the review pipeline','https://github.com/phinton1027/fbrp-saif-dev/compare/b8c1f5abf5e8...8e2d7d21de46','declined','low','low','gpt-5.4-mini','{\"risk\":\"low\",\"verdict\":\"Documentation-only change; no code, configuration, or runtime behavior affected.\",\"recommendation\":\"approve\",\"securityFindings\":[],\"summary\":{\"purpose\":\"Adds a test note to the README to verify the review pipeline.\",\"added\":[\"One README sentence about the pipeline test.\"],\"removed\":[],\"changed\":[\"README.md documentation only.\"]},\"targets\":[\"docs\"],\"compatibilityNotes\":\"No impact on game, API, website, bots, or database behavior.\",\"commits\":[{\"sha\":\"8e2d7d21de46\",\"message\":\"Test the review pipeline\",\"author\":\"phinton1027\"}]}','[]','[{\"name\":\"README.md\",\"status\":\"modified\",\"additions\":2,\"deletions\":0}]','--- modified README.md (+2 -0)\n@@ -7,3 +7,5 @@ This repository is the only place you work in. It does not contain any Florida B\n - Describe in each commit message what the change does and which area it belongs to.\n - Do not add compiled files, archives, minified or obfuscated code, credentials or webhooks. Do not add outbound HTTP calls unless the feature needs them and the commit says why.\n - Nothing here is deployed automatically. If the owner accepts a change, it is re-implemented in the real project by our own tooling.\n+\n+_Pipeline check: this line was added by the server owner to test the review flow._\n\n',NULL,'1792709356133','anon_744077356f3772c3cd07464a','1792809049008',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1792709333226','1792809049008'),
(2,'phinton1027/fbrp-saif-dev','main','anon_43b03df6bb51ac8ef9db','anon_1eabcd8287b89dbe54d4','phinton1027',1,'Add game, api, website, bots and docs folders','https://github.com/phinton1027/fbrp-saif-dev/compare/8e2d7d21de46...36f858774d2c','declined','low','low','gpt-5.4-mini','{\"risk\":\"low\",\"verdict\":\"Repo structure only; no executable code added.\",\"recommendation\":\"approve\",\"securityFindings\":[],\"summary\":{\"purpose\":\"Add top-level folders and short guidance for where future code should go.\",\"added\":[\"api/README.md\",\"bots/README.md\",\"docs/README.md\",\"game/README.md\",\"website/README.md\"],\"removed\":[],\"changed\":[\"Created empty project areas for API, bots, docs, game, and website work.\"]},\"targets\":[\"api\",\"bots\",\"docs\",\"game\",\"website\"],\"compatibilityNotes\":\"No runtime impact. Documentation-only change.\",\"commits\":[{\"sha\":\"36f858774d2c\",\"message\":\"Add game, api, website, bots and docs folders\",\"author\":\"phinton1027\"}]}','[]','[{\"name\":\"api/README.md\",\"status\":\"added\",\"additions\":3,\"deletions\":0},{\"name\":\"bots/README.md\",\"status\":\"added\",\"additions\":3,\"deletions\":0},{\"name\":\"docs/README.md\",\"status\":\"added\",\"additions\":3,\"deletions\":0},{\"name\":\"game/README.md\",\"status\":\"added\",\"additions\":3,\"deletions\":0},{\"name\":\"website/README.md\",\"status\":\"added\",\"additions\":3,\"deletions\":0}]','--- added api/README.md (+3 -0)\n@@ -0,0 +1,3 @@\n+# api\n+\n+Backend and API code. Describe any endpoints, request shapes and database tables in the commit message.\n\n--- added bots/README.md (+3 -0)\n@@ -0,0 +1,3 @@\n+# bots\n+\n+Discord bot code and commands.\n\n--- added docs/README.md (+3 -0)\n@@ -0,0 +1,3 @@\n+# docs\n+\n+Notes, specs and screenshots that explain your changes.\n\n--- added game/README.md (+3 -0)\n@@ -0,0 +1,3 @@\n+# game\n+\n+FiveM resources: Lua client and server scripts, NUI, config. One folder per resource, for example `game/my_resource/`.\n\n--- added website/README.md (+3 -0)\n@@ -0,0 +1,3 @@\n+# website\n+\n+Website and portal pages: HTML, CSS and JavaScript.\n\n',NULL,'1792710770414','anon_744077356f3772c3cd07464a','1792809046294',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1792710746343','1792809046294');
